// Banco de questões e comentários das alternativas – Simulado PQO Compliance (Guia Por Dentro da B3)
var D=[{"n":1,"tit":"I","titn":"Aspectos institucionais","cap":"I","capn":"Sistema Financeiro Nacional","stem":"Os pilares da estrutura atual do Sistema Financeiro Nacional foram criados pela:","opts":[["a","Lei nº 4.595/1964."],["b","Lei nº 6.385/1976."],["c","Lei nº 6.404/1976."],["d","Lei nº 4.728/1965."]],"ans":"a","exp":"Os pilares da estrutura atual do Sistema Financeiro Nacional foram dados pela Lei nº 4.595/1964, conhecida como a Lei da Reforma Bancária, que criou o Conselho Monetário Nacional (CMN) e o Banco Central do Brasil (Bacen), além de ter estabelecido as normas operacionais e os procedimentos aos quais as demais instituições estariam subordinadas.","pg":45},{"n":2,"tit":"I","titn":"Aspectos institucionais","cap":"I","capn":"Sistema Financeiro Nacional","stem":"O mercado em que se concentram as operações para controle de oferta de moeda e taxas de juro de curto prazo, com o objetivo de garantir a liquidez da economia, é chamado de:","opts":[["a","mercado de crédito."],["b","mercado monetário."],["c","mercado de capitais."],["d","mercado de câmbio."]],"ans":"b","exp":"Mercado monetário é o mercado em que se concentram as operações para controle de oferta de moeda e taxas de juro de curto prazo, com o objetivo de garantir a liquidez da economia.","pg":45},{"n":3,"tit":"I","titn":"Aspectos institucionais","cap":"I","capn":"Sistema Financeiro Nacional","stem":"O órgão responsável pela proteção da captação de poupança popular em investimentos realizados em planos de previdência complementar aberta é:","opts":[["a","o Bacen."],["b","a CVM."],["c","a Susep."],["d","a Previc."]],"ans":"c","exp":"Compete à Susep proteger a captação de poupança popular, realizada por meio de operações de seguro, previdência complementar aberta, capitalização e resseguro.","pg":45},{"n":4,"tit":"I","titn":"Aspectos institucionais","cap":"II","capn":"Infraestrutura do mercado","stem":"O sistema de liquidação que permite que ativos sejam transferidos e liquidados por meio de registros eletrônicos chama-se:","opts":[["a","book entry."],["b","best execution."],["c","electronic shares."],["d","uncertificated shares."]],"ans":"a","exp":"O sistema de liquidação que permite que ativos sejam transferidos e liquidados por meio de registros eletrônicos, de acordo com regras preestabelecidas de compensação, chama-se book entry.","pg":67},{"n":5,"tit":"I","titn":"Aspectos institucionais","cap":"II","capn":"Infraestrutura do mercado","stem":"O regime que busca mitigar conflitos de interesses que possam surgir na execução de ordens dos clientes pelos intermediários, assegurando que essas ordens serão executadas para proporcionar o melhor resultado possível aos clientes é chamado de:","opts":[["a","book entry."],["b","best execution."],["c","electronic shares."],["d","uncertificated shares."]],"ans":"b","exp":"A existência de um regime de best execution busca mitigar conflitos de interesses que possam surgir na execução de ordens dos clientes pelos intermediários, assegurando que essas ordens serão executadas para proporcionar o melhor resultado possível aos clientes e nas melhores condições para estes, mesmo existindo mais de um sistema de negociação e uma eventual divergência, ainda que temporária, entre os preços praticados em cada sistema.","pg":67},{"n":6,"tit":"I","titn":"Aspectos institucionais","cap":"II","capn":"Infraestrutura do mercado","stem":"O processo pelo qual uma contraparte central se interpõe entre as contrapartes originais de contratos negociados, tornando-se o comprador de todos os vendedores e o vendedor de todos os compradores, é chamado de:","opts":[["a","desmaterialização."],["b","liquidação diferida."],["c","novação."],["d","liquidação bruta."]],"ans":"c","exp":"Uma contraparte central se interpõe entre as contrapartes originais de contratos negociados, tornando-se o comprador de todos os vendedores e o vendedor de todos os compradores, por meio do processo de novação ou por meio de um instituto legal equivalente.","pg":67},{"n":7,"tit":"I","titn":"Aspectos institucionais","cap":"III","capn":"A B3 no mercado financeiro e de capitais","stem":"A _____ é uma infraestrutura de mercado que desempenha um papel fundamental na preservação da integridade dos ativos sob sua guarda e na proteção dos investidores em relação à propriedade desses ativos e direitos que deles se originam.","opts":[["a","câmara de compensação."],["b","central de registro."],["c","Câmara de Câmbio."],["d","central depositária."]],"ans":"d","exp":"A central depositária é uma infraestrutura de mercado que desempenha um papel fundamental na preservação da integridade dos ativos sob sua guarda e na proteção dos investidores em relação à propriedade desses ativos e direitos que deles se originam.","pg":92},{"n":8,"tit":"I","titn":"Aspectos institucionais","cap":"III","capn":"A B3 no mercado financeiro e de capitais","stem":"O participante de negociação é aquele que atua para seus clientes por meio de um _____, que tem acesso direto ao sistema de negociação da B3.","opts":[["a","membro de compensação."],["b","participante de negociação pleno (PNP)."],["c","participante de liquidação."],["d","banco de investimento."]],"ans":"b","exp":"O participante de negociação é aquele que atua para seus clientes por meio de um participante de negociação pleno (PNP), que tem acesso direto ao sistema de negociação da B3.","pg":92},{"n":9,"tit":"I","titn":"Aspectos institucionais","cap":"III","capn":"A B3 no mercado financeiro e de capitais","stem":"_____ é o nome do mecanismo que analisa e julga as reclamações dirigidas ao mercado para o ressarcimento de prejuízos. Ele é mantido pela B3 e administrado pela BSM, para assegurar a todos os investidores o ressarcimento de até R$ 200 mil por prejuízos, em cada ocorrência.","opts":[["a","BSM."],["b","MRP."],["c","PAD."],["d","RPB3."]],"ans":"b","exp":"O MRP, mantido pela B3 e administrado pela BSM, assegura a todos os investidores o ressarcimento de até R$ 200 mil por prejuízos, comprovadamente, causados por erros ou omissões de participantes dos mercados administrados pela B3 (corretoras e distribuidoras de títulos e valores mobiliários), seus administradores ou prepostos, em relação à intermediação de operações de bolsa com valores mobiliários (como compra e venda de ações, derivativos e fundos listados) e serviços de custódia. O ressarcimento é devido para cada ocorrência.","pg":92},{"n":10,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Além da distribuição de dividendos, a empresa pode remunerar seus acionistas por meio de:","opts":[["a","juros sobre o capital próprio."],["b","rendimentos fixos."],["c","rendimentos variáveis."],["d","ganho de capital."]],"ans":"a","exp":"Além da distribuição de dividendos, a empresa pode remunerar seus acionistas por meio de pagamento de juros sobre o capital próprio, com base em reservas patrimoniais de lucros retidos em exercícios anteriores.","pg":159},{"n":11,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"O índice Ibovespa é um índice de:","opts":[["a","retorno total ponderado por pesos iguais."],["b","retorno total ponderado por capitalização de mercado."],["c","retorno total ponderado por pesos diferenciados."],["d","retorno total ponderado por liquidez."]],"ans":"d","exp":"O índice Ibovespa é um índice de retorno total ponderado por liquidez.","pg":159},{"n":12,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"A decisão de emitir BDR Nível I Não Patrocinado (BDR NP N1) parte de uma instituição depositária estabelecida no Brasil, que solicita o registro do programa à CVM e à B3,","opts":[["a","com envolvimento da empresa estrangeira emissora do lastro dos BDRs."],["b","sem envolvimento da empresa estrangeira emissora do lastro dos BDRs."],["c","com participação das bolsas estrangeiras."],["d","com empresas sediadas em qualquer país."]],"ans":"b","exp":"A decisão de emitir BDR Nível I Não Patrocinado (BDR NP N1) parte de uma instituição depositária estabelecida no Brasil, que solicita o registro do programa à CVM e à B3, sem envolvimento da empresa estrangeira emissora do lastro dos BDRs.","pg":159},{"n":13,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"O _____ é uma operação realizada no mercado de balcão, na qual dois agentes acertam, na data zero, a cotação pela qual liquidarão a operação de câmbio entre duas moedas na data do vencimento do contrato.","opts":[["a","contrato futuro de moedas."],["b","contrato a termo de moedas."],["c","contrato futuro de dólar."],["d","contrato a termo de mercadorias."]],"ans":"b","exp":"O contrato a termo de moedas é uma operação realizada no mercado de balcão, na qual dois agentes acertam, na data zero, a cotação pela qual liquidarão a operação de câmbio entre duas moedas na data do vencimento do contrato.","pg":243},{"n":14,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"Os participantes do mercado de derivativos são:","opts":[["a","o hedger e o especulador."],["b","o hedger e o arbitrador."],["c","o hedger, o arbitrador e o especulador."],["d","o arbitrador e o especulador."]],"ans":"c","exp":"Os participantes do mercado de derivativos são o hedger, o arbitrador e o especulador.","pg":243},{"n":15,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"O contrato futuro de DDI negocia o cupom cambial chamado de:","opts":[["a","cupom limpo."],["b","cupom sintético."],["c","cupom a termo."],["d","cupom sujo."]],"ans":"d","exp":"O contrato futuro de DDI negocia o cupom cambial chamado de cupom sujo.","pg":243},{"n":16,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"Em parceria com o Tesouro Nacional, a B3 operacionaliza o sistema _____, por meio do qual investidores (pessoa física) podem adquirir títulos públicos federais disponibilizados diretamente pelo Tesouro Nacional.","opts":[["a","Selic."],["b","Tesouro Direto."],["c","Cetip."],["d","Puma."]],"ans":"b","exp":"Em parceria com o Tesouro Nacional, a B3 operacionaliza o sistema Tesouro Direto, por meio do qual investidores (pessoa física) podem adquirir títulos públicos federais disponibilizados diretamente pelo Tesouro Nacional.","pg":276},{"n":17,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"Quanto _____ a duration, _____ é o período de tempo para o investidor recuperar o valor investido e _____ é a exposição ao risco.","opts":[["a","maior; maior; menor."],["b","maior; maior; maior."],["c","maior; menor; maior."],["d","maior; menor; menor."]],"ans":"b","exp":"Quanto maior a duration, maior é o período de tempo para o investidor recuperar o valor investido e maior é a exposição ao risco","pg":276},{"n":18,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"É um título de crédito nominativo, de livre negociação, representativo de promessa de pagamento em dinheiro emitido com base em lastro de recebíveis originados de negócios entre produtores rurais.","opts":[["a","CRI."],["b","CDB."],["c","LTN."],["d","CRA."]],"ans":"d","exp":"O Certificado de Recebíveis do Agronegócio (CRA) é um título de crédito nominativo, de livre negociação, representativo de promessa de pagamento em dinheiro emitido com base em lastro de recebíveis originados de negócios entre produtores rurais.","pg":276},{"n":19,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"IV","capn":"Mercado de câmbio","stem":"A Câmara de Câmbio adota o modelo de pagamento contra pagamento. As operações podem ser liquidadas em:","opts":[["a","D+0 ou D+1."],["b","D+1 ou D+2."],["c","D+0, D+1 ou D+2."],["d","D+0."]],"ans":"c","exp":"A Câmara de Câmbio adota o modelo de pagamento contra pagamento. As operações podem ser liquidadas em D+0 (no mesmo dia), D+1 ou D+2, de acordo com a escolha das partes envolvidas.","pg":295},{"n":20,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"IV","capn":"Mercado de câmbio","stem":"A plataforma eletrônica da B3 que permite a negociação de dólar pronto chama-se:","opts":[["a","Puma Trading System."],["b","Sisbex."],["c","BovespaFix."],["d","Tradenet."]],"ans":"a","exp":"A plataforma eletrônica da B3 Puma Trading System permite a negociação de dólar pronto.","pg":295},{"n":21,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"IV","capn":"Mercado de câmbio","stem":"As taxas _____ de compra e de venda correspondem, respectivamente, às médias aritméticas das taxas de compra e de venda das consultas realizadas diariamente.","opts":[["a","PTAX."],["b","PCAM."],["c","Reuters."],["d","Taxa B3."]],"ans":"a","exp":"As taxas PTAX de compra e de venda correspondem, respectivamente, às médias aritméticas das taxas de compra e de venda das consultas realizadas diariamente.","pg":295},{"n":22,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"V","capn":"Fundos de investimento","stem":"A menor fração do patrimônio líquido de um fundo de investimento é chamada de:","opts":[["a","valor de emissão."],["b","cota."],["c","valor financeiro."],["d","quantidade."]],"ans":"b","exp":"A cota é a fração do patrimônio líquido de um fundo de investimento utilizada como referência para a realização de aplicações e resgates.","pg":324},{"n":23,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"V","capn":"Fundos de investimento","stem":"Fundos constituídos por prazo indeterminado, nos quais as aplicações e os resgates podem ser feitos a qualquer momento, são chamados de:","opts":[["a","fundos fechados."],["b","fundos exclusivos."],["c","fundos abertos."],["d","fundos ativos."]],"ans":"c","exp":"Fundos abertos são condomínios constituídos por prazo indeterminado, nos quais as aplicações e os resgates podem ser feitos a qualquer momento.","pg":324},{"n":24,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"V","capn":"Fundos de investimento","stem":"O fundo de investimento em índice com cotas negociáveis em bolsa como se fossem ações é chamado de:","opts":[["a","Fundo de renda fixa."],["b","Fundo de ações."],["c","Fundo imobiliário."],["d","Exchange traded fund (ETF)."]],"ans":"d","exp":"Exchange traded fund (ETF) é um fundo de investimento em índice, com cotas negociáveis em bolsa, como se fossem ações.","pg":324},{"n":25,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VI","capn":"Clubes de investimento","stem":"A menor fração do patrimônio de um clube de investimento é chamada de:","opts":[["a","valor de emissão."],["b","cota."],["c","valor financeiro."],["d","quantidade."]],"ans":"b","exp":"A menor fração do patrimônio de um clube de investimento é chamada de cota.","pg":334},{"n":26,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VI","capn":"Clubes de investimento","stem":"A entidade responsável pelo registro dos clubes de investimento é:","opts":[["a","a B3."],["b","a CVM."],["c","o Bacen."],["d","a BSM."]],"ans":"a","exp":"A entidade responsável pelo registro dos clubes de investimento é a B3.","pg":334},{"n":27,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VI","capn":"Clubes de investimento","stem":"A distribuição de cotas de clube de investimento por meio de serviços públicos de comunicação é algo:","opts":[["a","permitido."],["b","vedado."],["c","permitido com ressalvas."],["d","vedado com ressalvas."]],"ans":"b","exp":"A distribuição de cotas por meio de serviços públicos de comunicação é algo vedado. Exemplos desses meios são a imprensa, o rádio, a televisão e as páginas abertas ao público na rede mundial de computadores. Também é vedado o envio de malas diretas, inclusive por correio eletrônico.","pg":334},{"n":28,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VII","capn":"Outros ativos e serviços","stem":"A versão brasileira das Notas Estruturadas é chamada de:","opts":[["a","COE."],["b","LIG."],["c","vendor."],["d","CDB."]],"ans":"a","exp":"A versão brasileira das Notas Estruturadas é chamada de COE – Certificado de Operações Estruturadas.","pg":352},{"n":29,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VII","capn":"Outros ativos e serviços","stem":"Os Certificados de Potencial Adicional de Construção (Cepacs) são valores mobiliários emitidos _____ e utilizados como meio de pagamento de contrapartida para a outorga de direito urbanístico adicional dentro do perímetro de uma operação urbana consorciada.","opts":[["a","pela União."],["b","pelas prefeituras."],["c","pelos estados."],["d","pelas empresas."]],"ans":"b","exp":"Os Certificados de Potencial Adicional de Construção (Cepacs) são valores mobiliários emitidos pelas prefeituras e utilizados como meio de pagamento de contrapartida para a outorga de direito urbanístico adicional dentro do perímetro de uma operação urbana consorciada.","pg":352},{"n":30,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VII","capn":"Outros ativos e serviços","stem":"O serviço que envia, em tempo real, para qualquer lugar do mundo, informações geradas pela bolsa e notícias econômicas sobre o mercado de ações e derivativos é chamado de:","opts":[["a","vendor."],["b","gestão de garantias."],["c","market data."],["d","Cepac."]],"ans":"c","exp":"O market data, da B3, é um serviço que envia, em tempo real, para qualquer lugar do mundo, informações geradas pela bolsa e notícias econômicas sobre o mercado de ações e derivativos.","pg":352},{"n":31,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Nas operações de renda fixa com prazo menor que 30 dias, incide:","opts":[["a","IOF e, em seguida, IRF."],["b","IRF e, em seguida, IOF."],["c","apenas IOF."],["d","apenas IRF."]],"ans":"a","exp":"Nas operações de renda fixa com prazo menor que 30 dias, incide IOF e, em seguida, IRF.","pg":394},{"n":32,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"São isentos do imposto sobre a renda ou tributados à alíquota 0%, quando auferidos por pessoa física, os rendimentos auferidos por:","opts":[["a","depósitos de poupança e certificados de depósito bancário."],["b","certificados de depósito bancário e letras hipotecárias."],["c","certificados de recebíveis imobiliários e letras de crédito imobiliário."],["d","certificados de depósito bancário e letras de crédito imobiliário."]],"ans":"c","exp":"São isentos do imposto sobre a renda ou tributados à alíquota 0%, quando auferidos por pessoa física, os rendimentos auferidos por certificados de recebíveis imobiliários e letras de crédito imobiliário.","pg":394},{"n":33,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"No caso do Imposto de Renda, estão sujeitos a um regime especial de tributação os investidores:","opts":[["a","não residentes no Brasil que não sejam domiciliados em paraísos fiscais."],["b","não residentes no Brasil que sejam domiciliados em paraísos fiscais."],["c","não residentes no Brasil, sejam domiciliados em paraísos fiscais ou não."],["d","residentes e não residentes no Brasil."]],"ans":"a","exp":"No caso do Imposto de Renda, estão sujeitos a um regime especial de tributação os investidores não residentes no Brasil que não sejam domiciliados em paraísos fiscais.","pg":394},{"n":34,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"I","capn":"Cadastro de investidores residentes","stem":"De acordo com a regulamentação em vigor, as centrais depositárias devem manter sistema centralizado de cadastro de investidores e estruturas de contas de depósito em nome:","opts":[["a","da corretora de valores."],["b","do banco custodiante."],["c","do beneficiário final das transações."],["d","do sistema de custódia."]],"ans":"c","exp":"De acordo com a regulamentação em vigor, as centrais depositárias devem manter sistema centralizado de cadastro de investidores e estruturas de contas de depósito em nome do beneficiário final das transações ocorridas no mercado de capitais.","pg":410},{"n":35,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"I","capn":"Cadastro de investidores residentes","stem":"De acordo com a regulamentação em vigor, os investidores serão identificados:","opts":[["a","no momento em que a operação for realizada em seu nome."],["b","no momento em que a operação for realizada em nome da corretora."],["c","no momento da liquidação da operação."],["d","no momento do registro da operação na conta máster."]],"ans":"a","exp":"De acordo com a regulamentação em vigor, os investidores serão identificados no momento em que a operação for realizada em seu nome.","pg":410},{"n":36,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"I","capn":"Cadastro de investidores residentes","stem":"O repasse entre contas é feito:","opts":[["a","entre dois PNP, quando houver contrato específico entre as partes e desde que exista um vínculo de repasse entre eles."],["b","entre dois PNP ou entre um PNP e um PL, quando houver contrato específico entre as partes."],["c","entre dois PNP, desde que exista um vínculo de repasse entre eles."],["d","entre dois PNP ou entre um PNP e um PL, quando houver contrato específico entre as partes e desde que exista um vínculo de repasse entre eles."]],"ans":"d","exp":"O repasse de operações é feito entre dois PNP ou entre um PNP e um PL, quando houver contrato específico entre as partes e desde que exista um vínculo de repasse entre eles.","pg":410},{"n":37,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"II","capn":"Cadastro de investidores não residentes","stem":"A Comissão de Valores Mobiliários (CVM), o Banco Central do Brasil (Bacen), o Conselho Monetário Nacional (CMN) e a própria B3 estabelecem normas e procedimentos relativos ao cadastramento para _____, que desejam atuar no mercado financeiro do Brasil.","opts":[["a","investidores residentes e domiciliados."],["b","investidores residentes e não residentes."],["c","investidores não residentes."],["d","investidores residentes e não domiciliados."]],"ans":"b","exp":"A Comissão de Valores Mobiliários (CVM), o Banco Central do Brasil (Bacen), o Conselho Monetário Nacional (CMN) e a própria B3 estabelecem normas e procedimentos relativos ao cadastramento para investidores residentes e não residentes, que desejam atuar no mercado financeiro do Brasil.","pg":419},{"n":38,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"II","capn":"Cadastro de investidores não residentes","stem":"Em linhas gerais, a Resolução Conjunta BACEN/CVM nº 13/2024 dá acesso ao investidor não residente:","opts":[["a","aos mesmos mercados disponíveis ao investidor residente."],["b","a mercados específicos."],["c","apenas ao mercado de juros."],["d","apenas ao mercado de ações."]],"ans":"a","exp":"Em linhas gerais, a Resolução Conjunta BACEN/CVM nº 13/2024 dá acesso ao investidor não residente aos mesmos mercados disponíveis ao investidor residente, havendo a necessidade de o investidor ser registrado no Brasil e internalizar recursos, em moeda local, mediante contratação de operações de câmbio.","pg":419},{"n":39,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"II","capn":"Cadastro de investidores não residentes","stem":"O responsável por realizar o registro na CVM em nome do investidor não residente é o:","opts":[["a","responsável fiscal."],["b","representante legal."],["c","custodiante."],["d","o investidor."]],"ans":"b","exp":"O representante legal é responsável por realizar o registro na CVM.","pg":419},{"n":40,"tit":"IV","titn":"Gestão de risco","cap":"I","capn":"Gestão de risco na Câmara","stem":"O risco de perdas em decorrência da variação do preço dos ativos e contratos em valor superior ao das garantias é chamado de:","opts":[["a","risco de mercado."],["b","risco de crédito."],["c","risco de liquidez."],["d","risco operacional."]],"ans":"a","exp":"O risco de perdas em decorrência da variação do preço dos ativos e contratos em valor superior ao das garantias é chamado de risco de mercado.","pg":456},{"n":41,"tit":"IV","titn":"Gestão de risco","cap":"I","capn":"Gestão de risco na Câmara","stem":"A B3 assume a posição de contraparte central para fins de liquidação das obrigações resultantes de operações por ela aceitas para compensação e liquidação, exclusivamente em relação:","opts":[["a","aos participantes de negociação pleno (PNP)."],["b","aos participantes de liquidação (PL)."],["c","aos membros de compensação (MC)."],["d","aos comitentes."]],"ans":"c","exp":"A B3 assume a posição de contraparte central para fins de liquidação das obrigações resultantes de operações por ela aceitas para compensação e liquidação, exclusivamente em relação aos membros de compensação.","pg":456},{"n":42,"tit":"IV","titn":"Gestão de risco","cap":"I","capn":"Gestão de risco na Câmara","stem":"A componente da estrutura de salvaguardas cujos recursos só podem ser usados em caso de inadimplência do participante contribuinte é chamada de:","opts":[["a","survivor pays."],["b","defaulter pays."],["c","third parties pay."],["d","modelo integrado."]],"ans":"b","exp":"A componente da estrutura de salvaguardas cujos recursos só podem ser usados em caso de inadimplência do participante contribuinte é chamada de defaulter pays.","pg":456},{"n":43,"tit":"IV","titn":"Gestão de risco","cap":"II","capn":"Risco corporativo e controles internos","stem":"A gestão operacional está relacionada a que linha de defesa?","opts":[["a","Introdutória."],["b","Primeira linha de defesa."],["c","Segunda linha de defesa."],["d","Terceira linha de defesa."]],"ans":"b","exp":"A primeira linha de defesa corresponde à gestão operacional e está relacionada à ação do próprio funcionário que executa determinado processo ou função.","pg":483},{"n":44,"tit":"IV","titn":"Gestão de risco","cap":"II","capn":"Risco corporativo e controles internos","stem":"Sobre a segunda linha de defesa de controles internos das instituições participantes, pode-se afirmar que:","opts":[["a","Trata-se da área que é dona, de fato, do risco daquele negócio."],["b","É desempenhada pela auditoria interna."],["c","Tem a função de averiguar se o risco chegou a se materializar."],["d","Avalia se os controles implementados estão funcionando adequadamente para prevenir o risco."]],"ans":"d","exp":"A segunda linha de defesa é desempenhada pela área de controles internos da organização. A principal função dessa área é avaliar se os controles implementados estão funcionando adequadamente para prevenir o risco. Ela não está necessariamente preocupada em averiguar se o risco chegou a se materializar alguma vez, mas sim se o mecanismo empregado para impedir que ele se materialize é eficaz.","pg":483},{"n":45,"tit":"IV","titn":"Gestão de risco","cap":"II","capn":"Risco corporativo e controles internos","stem":"A negociação excessiva ou giro excessivo da carteira do investidor com o único objetivo de gerar maior corretagem é chamada de:","opts":[["a","churning."],["b","front running."],["c","insider trading."],["d","framing."]],"ans":"a","exp":"Churning é a negociação excessiva ou giro excessivo da carteira do investidor com o único objetivo de gerar maior corretagem.","pg":483},{"n":46,"tit":"V","titn":"Negociação","cap":"I","capn":"Mercados organizados","stem":"Os titulares de uma opção de estilo americano:","opts":[["a","poderão exercê-la, mas não a qualquer tempo."],["b","poderão exercê-la, a qualquer tempo, a partir do pregão seguinte ao de sua aquisição, até a data de seu vencimento."],["c","poderão exercê-la somente na data de vencimento."],["d","poderão exercê-la em D+2."]],"ans":"b","exp":"Os titulares de opção de estilo americano poderão exercê-la, a qualquer tempo, a partir do pregão seguinte ao de sua aquisição, até a data de seu vencimento.","pg":502},{"n":47,"tit":"V","titn":"Negociação","cap":"I","capn":"Mercados organizados","stem":"Os contratos futuros possuem estrutura previamente padronizada por regulamentação de bolsa, estabelecendo todas as características do produto negociado, tais como:","opts":[["a","cotação e quantidade máxima."],["b","liquidação bruta e data de vencimento."],["c","qualquer data de vencimento."],["d","cotação, data de vencimento e tipo de liquidação."]],"ans":"d","exp":"Os contratos futuros possuem estrutura previamente padronizada por regulamentação de bolsa, estabelecendo todas as características do produto negociado, tais como cotação, data de vencimento e tipo de liquidação.","pg":502},{"n":48,"tit":"V","titn":"Negociação","cap":"I","capn":"Mercados organizados","stem":"A obrigação exigida de um lançador de uma opção de venda é que ele:","opts":[["a","empreste ao titular da opção, até uma data prefixada, um lote padrão de determinado ativo a um preço previamente estipulado."],["b","compre do titular da opção, até uma data prefixada, um lote padrão de determinado ativo a um preço previamente estipulado."],["c","vende ao titular da opção, até uma data prefixada, um lote padrão de determinado ativo a um preço previamente estipulado."],["d","Não há nenhuma obrigação."]],"ans":"b","exp":"A obrigação exigida de um lançador de uma opção de venda é que ele compre do titular da opção, até uma data prefixada, um lote padrão de determinado ativo a um preço previamente estipulado.","pg":502},{"n":49,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"Compete _____, dentro de sua esfera de atuação, apurar e punir as infrações dispostas no Regulamento de Negociação da B3, nas normas que o complementam ou na legislação em vigor, aplicando, conforme o caso, as penalidades previstas em seu estatuto social, na forma de seu regulamento processual.","opts":[["a","à B3."],["b","à BSM."],["c","à CVM."],["d","ao Bacen."]],"ans":"b","exp":"Compete à BSM, dentro de sua esfera de atuação, apurar e punir as infrações dispostas no regulamento de negociação da B3, nas normas que o complementam ou na legislação em vigor, aplicando, conforme o caso, as penalidades previstas em seu estatuto social, na forma de seu regulamento processual.","pg":540},{"n":50,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"O procedimento operacional que interrompe a negociação de ativos e demais valores mobiliários em momentos atípicos de mercado, em que há excessiva volatilidade, é chamado de:","opts":[["a","circuit breaker."],["b","after-hours."],["c","co-location."],["d","STP."]],"ans":"a","exp":"O circuit breaker é o procedimento operacional que interrompe a negociação de ativos e demais valores mobiliários em momentos atípicos de mercado, em que há excessiva volatilidade.","pg":540},{"n":51,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"O participante cadastrado que tem suas ordens transmitidas ao ambiente de negociação por meio do registro de ofertas é chamado de:","opts":[["a","PNP."],["b","PN."],["c","comitente."],["d","formador de mercado."]],"ans":"c","exp":"O comitente é um participante cadastrado que tem suas ordens transmitidas ao ambiente de negociação por meio do registro de ofertas e suas operações próprias realizadas no ambiente de negociação, por sua conta e ordem, por intermédio e responsabilidade de um participante de negociação pleno ou participante de negociação.","pg":540},{"n":52,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"I","capn":"Câmara B3","stem":"Que participante utiliza sua conta reservas bancárias ou conta de liquidação para efetuar ou receber os pagamentos referentes aos processos de liquidação com a câmara?","opts":[["a","O participante de liquidação."],["b","O banco liquidante."],["c","O participante de negociação."],["d","O membro de compensação."]],"ans":"b","exp":"Liquidante (ou banco liquidante) é o participante que utiliza sua conta reservas bancárias ou conta de liquidação para efetuar ou receber os pagamentos referentes aos processos de liquidação dos membros de compensação (MC) com a câmara.","pg":566},{"n":53,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"I","capn":"Câmara B3","stem":"A Câmara B3 assume a posição de contraparte central na liquidação, exclusivamente, perante o:","opts":[["a","comitente."],["b","participante de negociação."],["c","participante de liquidação."],["d","membro de compensação."]],"ans":"d","exp":"A Câmara B3 assume a posição de contraparte central na liquidação, exclusivamente, perante o membro de compensação.","pg":566},{"n":54,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"I","capn":"Câmara B3","stem":"O participante que não efetuar a liquidação de sua obrigação, na forma estabelecida pela câmara, em decorrência de insuficiência financeira, poderá ser declarado:","opts":[["a","insolvente."],["b","concordatário."],["c","inadimplente."],["d","devedor operacional."]],"ans":"c","exp":"O participante que não efetuar a liquidação de sua obrigação, na forma estabelecida pela câmara, em decorrência de insuficiência financeira, poderá ser declarado inadimplente.","pg":566},{"n":55,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"II","capn":"Processos operacionais da Câmara B3","stem":"As operações de compra e de venda de um mesmo ativo, realizadas em uma mesma data de negociação, por um mesmo participante e em uma mesma conta de posição são consideradas, pela câmara,","opts":[["a","day trade."],["b","swing trade."],["c","front runner."],["d","spot."]],"ans":"a","exp":"A câmara considera day trade as operações de compra e de venda de um mesmo ativo, realizadas em uma mesma data de negociação, por um mesmo participante e em uma mesma conta de posição.","pg":598},{"n":56,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"II","capn":"Processos operacionais da Câmara B3","stem":"As modalidades das operações registradas nos ambientes de registro podem ser realizadas","opts":[["a","com garantia e sem garantia."],["b","com garantia, sem garantia e com garantia parcial."],["c","apenas sem garantia."],["d","apenas com garantia."]],"ans":"b","exp":"As modalidades das operações registradas nos ambientes de registro podem ser realizadas com garantia, sem garantia e com garantia parcial.","pg":598},{"n":57,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"II","capn":"Processos operacionais da Câmara B3","stem":"A modalidade de operação em que a câmara não atua como contraparte central de nenhuma das partes da operação, mas operacionaliza o processo de liquidação é chamada de:","opts":[["a","com garantia."],["b","com garantia parcial."],["c","sem garantia parcial."],["d","sem garantia com liquidação bruta."]],"ans":"d","exp":"A modalidade de operação em que a câmara não atua como contraparte central de nenhuma das partes da operação, mas operacionaliza o processo de liquidação é chamada de sem garantia com liquidação bruta.","pg":598},{"n":58,"tit":"VII","titn":"Central depositária","cap":"I","capn":"Central depositária da B3","stem":"Os custos e encargos cobrados pela B3 estão descritos em sua política de tarifação, que é divulgada:","opts":[["a","por comunicado."],["b","por meio de ofício circular."],["c","por informe ao mercado."],["d","pelos membros de compensação."]],"ans":"b","exp":"Os custos e encargos cobrados pela B3 estão descritos em sua política de tarifação, que é divulgada por meio de ofício circular.","pg":613},{"n":59,"tit":"VII","titn":"Central depositária","cap":"I","capn":"Central depositária da B3","stem":"Conforme estabelecido em sua _____ e demais normas relacionadas, a B3 garante a continuidade de suas atividades em caso de desastre no centro de processamento de dados principal, possuindo unidade de contingência externa, conforme a legislação em vigor.","opts":[["a","política de continuidade de negócios."],["b","política de tarifação."],["c","política de processamento de dados."],["d","política de contingência."]],"ans":"a","exp":"Conforme estabelecido em sua política de continuidade de negócios e demais normas relacionadas, a B3 garante a continuidade de suas atividades em caso de desastre no centro de processamento de dados principal, possuindo unidade de contingência externa, conforme a legislação em vigor.","pg":613},{"n":60,"tit":"VII","titn":"Central depositária","cap":"I","capn":"Central depositária da B3","stem":"É o participante detentor de autorização de acesso para custódia perante a central depositária da B3.","opts":[["a","Sistema externo."],["b","emissor."],["c","escriturador."],["d","agente de custódia."]],"ans":"d","exp":"O agente de custódia é o participante detentor de autorização de acesso para custódia perante a central depositária da B3.","pg":613},{"n":61,"tit":"VII","titn":"Central depositária","cap":"II","capn":"Processos operacionais da central depositária da B3","stem":"A central depositária da B3 oferece um serviço disponível em seu endereço eletrônico denominado:","opts":[["a","Serviço de Atendimento ao Investidor."],["b","Área do Investidor."],["c","Consulta de Participantes."],["d","Extrato Eletrônico."]],"ans":"b","exp":"A central depositária da B3 oferece um serviço disponível em seu endereço eletrônico denominado Área do Investidor.","pg":629},{"n":62,"tit":"VII","titn":"Central depositária","cap":"II","capn":"Processos operacionais da central depositária da B3","stem":"As contas de depósito são identificadas e numeradas _____, sendo divididas em carteiras com características e finalidades específicas.","opts":[["a","por agente de custódia."],["b","por comitente."],["c","por agente de custódia e por comitente."],["d","por agente de custódia e por comitente e conta de ativos."]],"ans":"c","exp":"As contas de depósito são identificadas e numeradas por agente de custódia e por comitente, sendo divididas em carteiras com características e finalidades específicas.","pg":629},{"n":63,"tit":"VII","titn":"Central depositária","cap":"II","capn":"Processos operacionais da central depositária da B3","stem":"O serviço de guarda centralizada de ativos da central depositária da B3 consiste no controle dos saldos dos ativos, bem como das respectivas movimentações de ativos, em forma:","opts":[["a","escritural, por meio de registros eletrônicos."],["b","digital, por meio de registros eletrônicos."],["c","física."],["d","de controle de títulos fungíveis."]],"ans":"a","exp":"O serviço de guarda centralizada de ativos da central depositária da B3 consiste, sobretudo, no controle dos saldos dos ativos, bem como das respectivas movimentações de ativos, em forma escritural, por meio de registros eletrônicos.","pg":629},{"n":64,"tit":"VIII","titn":"Compliance","cap":"I","capn":"Prevenção à lavagem de dinheiro, ao financiamento do terrorismo e ao financiamento da proliferação de armas de destruição em massa","stem":"Os clientes classificados como PEP:","opts":[["a","Devem ter tratamento específico no âmbito de PLD/FTP."],["b","Deve ser tratado como os demais por força da vedação à discriminação."],["c","Devem ter seu cadastro recusado."],["d","Devem ter todas suas operações informadas ao Coaf."]],"ans":"a","exp":"Os clientes classificados como PEP devem ter tratamento específico no âmbito de PLD/FTP.","pg":643},{"n":65,"tit":"VIII","titn":"Compliance","cap":"I","capn":"Prevenção à lavagem de dinheiro, ao financiamento do terrorismo e ao financiamento da proliferação de armas de destruição em massa","stem":"Considera-se cliente ativo aquele que:","opts":[["a","nos últimos 12 (doze) meses tenha: efetuado movimentação de sua conta-corrente ou posição de custódia, realizado operação no mercado de valores mobiliários; ou apresentado saldo e sua posição de custódia."],["b","nos últimos 18 (dezoito) meses tenha: efetuado movimentação de sua conta-corrente ou posição de custódia, realizado operação no mercado de valores mobiliários; ou apresentado saldo e sua posição de custódia."],["c","nos últimos 12 (doze) meses tenha: efetuado movimentação de sua conta-corrente."],["d","nos últimos 18 (dezoito) meses tenha: efetuado movimentação de sua conta-corrente ou posição de custódia, realizado operação de day trade."]],"ans":"a","exp":"O cliente é considerado ativo, desde que, nos últimos 12 meses, tenha efetuado movimentação de sua conta-corrente ou posição de custódia, realizado operação no mercado de valores mobiliários ou apresentado saldo e sua posição de custódia.","pg":643},{"n":66,"tit":"VIII","titn":"Compliance","cap":"I","capn":"Prevenção à lavagem de dinheiro, ao financiamento do terrorismo e ao financiamento da proliferação de armas de destruição em massa","stem":"A política de PLD/FTP deve:","opts":[["a","ser documentada, aprovada pela alta administração e mantida atualizada, e, no caso de conglomerados financeiros, devem ser estabelecidos mecanismos de intercâmbio de informações entre as áreas de controles internos das instituições do conglomerado para o cumprimento da política."],["b","ser documentada, aprovada pela alta administração e mantida atualizada, e, no caso de conglomerados financeiros, não devem ser estabelecidos mecanismos de intercâmbio de informações entre as áreas de controles internos das instituições do conglomerado."],["c","Ser tratada como confidencial e sigilosa."],["d","Ser aprovada pelo Bacen e CVM e informada ao Coaf."]],"ans":"a","exp":"A política de PLD/FTP, deve ser documentada, aprovada pela alta administração e mantida atualizada, e, no caso de conglomerados financeiros, devem ser estabelecidos mecanismos de intercâmbio de informações entre as áreas de controles internos das instituições do conglomerado para o cumprimento da política.","pg":643},{"n":67,"tit":"VIII","titn":"Compliance","cap":"II","capn":"Proteção de dados pessoais e privacidade","stem":"O profissional responsável pela comunicação em assuntos de proteção de dados e privacidade é chamado de:","opts":[["a","compliance officer."],["b","head de comunicação/marketing."],["c","encarregado/DPO."],["d","diretor de RH."]],"ans":"c","exp":"O encarregado/DPO é o responsável pela comunicação em assuntos de proteção de dados e privacidade.","pg":652},{"n":68,"tit":"VIII","titn":"Compliance","cap":"II","capn":"Proteção de dados pessoais e privacidade","stem":"O direito de exclusão de dados pessoais","opts":[["a","É absoluto, deve ser atendido pela empresa sempre sem ressalvas."],["b","Pode não ser atendido se houver outros direitos ou interesses que prevaleçam sem necessidade de justificativa."],["c","Pode não ser atendido se houver outros interesses ou direitos que prevaleçam e a empresa deve fundamentar o não atendimento da exclusão."],["d","Não é um pedido possível de ser feito."]],"ans":"c","exp":"O direito de exclusão de dados pessoais pode não ser atendido se houver outros interesses ou direitos que prevaleçam e a empresa deve fundamentar o não atendimento da exclusão.","pg":652},{"n":69,"tit":"VIII","titn":"Compliance","cap":"II","capn":"Proteção de dados pessoais e privacidade","stem":"O consentimento é:","opts":[["a","A única base legal prevista na LGPD."],["b","Irrevogável."],["c","Uma das dez bases legais previstas na LGPD."],["d","Essencial para tratamento de dados no mercado financeiro e de capitais."]],"ans":"c","exp":"O consentimento é uma das dez bases legais previstas na LGPD.","pg":652},{"n":70,"tit":"VIII","titn":"Compliance","cap":"III","capn":"Adequação ao perfil do cliente (suitability)","stem":"Caso o investidor envie ordem de operação divergente de seu perfil, o participante deve:","opts":[["a","Recusar e não executar."],["b","Recusar e informar o Coaf e a CVM."],["c","Aceitar e executar."],["d","Aceitar alertando o investidor."]],"ans":"d","exp":"O participante deve aceitar uma ordem divergente do perfil do investidor, mas deve alertá-lo sobre isso.","pg":662},{"n":71,"tit":"VIII","titn":"Compliance","cap":"III","capn":"Adequação ao perfil do cliente (suitability)","stem":"A pessoa natural com investimento superior a 1 milhão de reais, ao atestar essa condição nos termos exigidos pela CVM, será considerada:","opts":[["a","Investidor varejo."],["b","Investidor qualificado."],["c","Investidor Institucional."],["d","Investidor profissional."]],"ans":"b","exp":"O investidor qualificado é aquele que possui investimentos comprovados superiores a 1 milhão de reais.","pg":662},{"n":72,"tit":"VIII","titn":"Compliance","cap":"III","capn":"Adequação ao perfil do cliente (suitability)","stem":"O objetivo de investimento do cliente:","opts":[["a","Deve ser considerado sempre para fins de suitability."],["b","Nunca deve ser considerado para fins de suitability."],["c","É o único critério de suitability."],["d","É o critério mais importante para verificação de suitability."]],"ans":"a","exp":"O objetivo de investimento do cliente sempre deverá ser considerado para fins de suitability.","pg":662},{"n":73,"tit":"VIII","titn":"Compliance","cap":"IV","capn":"Operações ilícitas","stem":"A realização de operações de forma excessiva com o intuito de aumentar o pagamento de comissões é conhecido como:","opts":[["a","spoofing."],["b","layering."],["c","churning."],["d","OMC e Front Running."]],"ans":"c","exp":"Churning é a realização de operações de forma excessiva com o intuito de aumentar o pagamento de comissões.","pg":680},{"n":74,"tit":"VIII","titn":"Compliance","cap":"IV","capn":"Operações ilícitas","stem":"Ordem falsa para induzir o mercado com o objetivo de realizar operação no lado oposto do livro de ofertas é elemento de:","opts":[["a","spoofing."],["b","front running e layering."],["c","churning."],["d","OMC."]],"ans":"a","exp":"A ordem falsa para induzir o mercado é chamada de spoofing.","pg":680},{"n":75,"tit":"VIII","titn":"Compliance","cap":"IV","capn":"Operações ilícitas","stem":"No caso de spoofing, podem ser punidos por regulador e/ou autorregulador:","opts":[["a","Apenas o investidor."],["b","Apenas o participante de mercado."],["c","O investidor e participante de mercado"],["d","O investidor e o diretor responsável perante a CVM do participante."]],"ans":"c","exp":"No caso de spoofing, podem ser punidos o investidor e o participante de mercado.","pg":680},{"n":76,"tit":"VIII","titn":"Compliance","cap":"V","capn":"Segurança cibernética e segurança da informação","stem":"As regras de segurança cibernética para o sistema de distribuição de valores mobiliários são expedidas por:","opts":[["a","Bacen."],["b","CVM."],["c","Bacen e CVM."],["d","Bacen, CVM e ANPD."]],"ans":"c","exp":"As regras de segurança cibernética são expedidas pelo Bacen e CVM.","pg":688},{"n":77,"tit":"VIII","titn":"Compliance","cap":"V","capn":"Segurança cibernética e segurança da informação","stem":"A política de segurança da informação deve:","opts":[["a","Seguir modelo padrão do mercado expedido pelo Bacen."],["b","Seguir modelo padrão de mercado expedido pela CVM."],["c","Ser compatível com o porte, perfil e modelo de negócio da instituição."],["d","Considerar capital social, perfil de clientes e modelo de negócio da instituição."]],"ans":"c","exp":"A política da segurança da informação deve ser compatível com o porte, perfil e modelo de negócio da instituição.","pg":688},{"n":78,"tit":"VIII","titn":"Compliance","cap":"V","capn":"Segurança cibernética e segurança da informação","stem":"Com relação à contratação de serviços de armazenamento em nuvem:","opts":[["a","O prestador pode ser livremente escolhido."],["b","O prestador deve ser homologado pelo Bacen."],["c","O prestador deve estar em país cuja autoridade de supervisão tenha convênio para troca de informações com o Bacen."],["d","O prestador deve estar em lista divulgada anualmente pelo Bacen."]],"ans":"c","exp":"Para armazenamento na nuvem, o prestador deve estar em país cuja autoridade de supervisão tenha convênio para troca de informações com o Bacen.","pg":688},{"n":79,"tit":"VIII","titn":"Compliance","cap":"VI","capn":"Política de responsabilidade social, ambiental e climática (PRSAC)","stem":"A PRSAC deve cobrir riscos de natureza:","opts":[["a","social, ambiental e climática."],["b","socioambiental, socioeconômico e operacional."],["c","social, ambiental e demográfico."],["d","socioambiental, socioeconômico e geopolítico."]],"ans":"a","exp":"A PRSAC deve cobrir riscos de natureza social, ambiental e climática.","pg":693},{"n":80,"tit":"VIII","titn":"Compliance","cap":"VI","capn":"Política de responsabilidade social, ambiental e climática (PRSAC)","stem":"Com relação a conglomerados prudenciais, a PRSAC:","opts":[["a","Deve ser segregada, cada instituição possui a sua."],["b","Deve ser única, ou seja, uma PRSAC para todo conglomerado."],["c","Pode ser única para conglomerado e tratar apenas o que for comum a todas as empresas do grupo."],["d","Pode ser unificada, mas deve considerar aspectos de cada instituição."]],"ans":"d","exp":"Com relação a conglomerados prudenciais, a PRSAC pode ser unificada, mas deve considerar aspectos de cada instituição.","pg":693},{"n":81,"tit":"VIII","titn":"Compliance","cap":"VI","capn":"Política de responsabilidade social, ambiental e climática (PRSAC)","stem":"A documentação relativa a PRSAC:","opts":[["a","Deve ser arquivada por 10 anos."],["b","Deve ser mantida à disposição do Ministério do Meio Ambiente por 5 anos."],["c","Deve ser mantida à disposição do Banco Central por 5 anos."],["d","Deve ser mantida à disposição do Banco Central por 10 anos."]],"ans":"c","exp":"A documentação relativa a PRSAC deve ser mantida à disposição do Banco Central por 5 anos.","pg":693},{"n":82,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Segundo a Lei das S.A., qual é a participação mínima de ações ordinárias no capital social de uma companhia?","opts":[["a","25%"],["b","33%"],["c","50%"],["d","67%"]],"ans":"c","exp":"A Lei nº 6.404/1976 determina que a companhia deve ter, no mínimo, 50% do seu capital constituído de ações ordinárias; as preferenciais, em geral sem direito a voto, ficam limitadas aos demais 50%.","pg":99},{"n":83,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Qual característica é exclusiva do Novo Mercado em relação aos segmentos Nível 1 e Nível 2?","opts":[["a","Capital social composto apenas por ações ordinárias"],["b","Free float mínimo de 20% (ou regra alternativa)"],["c","Manutenção de ações preferenciais com tag along de 100%"],["d","Listagem sem oferta, com até sete anos para o IPO"]],"ans":"a","exp":"No Novo Mercado o capital social é composto apenas por ações ordinárias, com tag along de 100%.","pg":104},{"n":84,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Qual segmento de listagem permite que a empresa seja listada sem oferta e tenha até sete anos para realizar o IPO?","opts":[["a","Novo Mercado"],["b","Nível 2"],["c","Nível 1"],["d","Bovespa Mais"]],"ans":"d","exp":"O Bovespa Mais permite a listagem sem oferta: a empresa pode ser listada na B3 e tem até sete anos para realizar a oferta pública de ações (IPO).","pg":105},{"n":85,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"A distribuição gratuita de novas ações aos acionistas, proporcional às suas participações e resultante de aumento de capital por incorporação de reservas ou lucros, é chamada de:","opts":[["a","Subscrição"],["b","Bonificação"],["c","Desdobramento"],["d","Juros sobre capital próprio"]],"ans":"b","exp":"Bonificação é a distribuição gratuita de ações aos acionistas, proporcional às parcelas que possuem, resultante de aumento de capital por incorporação de reservas ou lucros em suspenso.","pg":100},{"n":86,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Uma companhia decide reunir cada dez ações existentes em uma só, sem alterar o valor total do investimento do acionista. Esse evento é chamado de:","opts":[["a","Grupamento (inplit)"],["b","Desdobramento (split)"],["c","Bonificação"],["d","Subscrição"]],"ans":"a","exp":"Grupamento (inplit) consiste em reunir várias ações em uma; o desdobramento (split) faz o inverso, dividindo as ações existentes. Em ambos, o valor do investimento não se altera.","pg":101},{"n":87,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"A ordem que deve ser executada somente a preço igual ou melhor do que o especificado pelo cliente é a ordem:","opts":[["a","A mercado"],["b","Administrada"],["c","Limitada"],["d","Casada"]],"ans":"c","exp":"A ordem limitada é aquela que deve ser executada somente a preço igual ou melhor do que o especificado pelo cliente.","pg":519},{"n":88,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"O cliente especifica apenas a quantidade e as características do ativo, deixando a execução a critério do PNP ou do PN. Trata-se da ordem:","opts":[["a","Stop"],["b","Administrada"],["c","Limitada"],["d","Casada"]],"ans":"b","exp":"Na ordem administrada o cliente especifica somente a quantidade e as características dos ativos, ficando a execução a critério do PNP ou do PN.","pg":519},{"n":89,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"A ordem cuja execução está vinculada à execução de outra ordem do cliente, podendo ser com ou sem limite de preço, é a ordem:","opts":[["a","Casada"],["b","On close"],["c","Stop"],["d","Administrada"]],"ans":"a","exp":"Ordem casada é aquela cuja execução está vinculada à execução de outra ordem do cliente, podendo ser com ou sem limite de preço.","pg":520},{"n":90,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"Quando o Ibovespa cai 10% em relação ao fechamento do dia anterior, o circuit breaker interrompe a negociação por:","opts":[["a","15 minutos"],["b","30 minutos"],["c","1 hora"],["d","Prazo definido pela B3"]],"ans":"b","exp":"Pelo circuit breaker, a queda de 10% do Ibovespa interrompe a negociação por 30 minutos; a de 15%, por 1 hora; na de 20%, a B3 pode suspender a negociação por prazo que ela definir.","pg":532},{"n":91,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"Reabertas as negociações após o primeiro acionamento do circuit breaker, se o Ibovespa atingir queda de 15%, a negociação é interrompida por:","opts":[["a","30 minutos"],["b","2 horas"],["c","1 hora"],["d","Até o fim do pregão"]],"ans":"c","exp":"Na queda de 15% do Ibovespa, após a reabertura, a negociação de ativos, derivativos e renda fixa privada é interrompida por 1 hora.","pg":532},{"n":92,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"No empréstimo de ativos, a B3, como contraparte de todos os contratos registrados, só autoriza a operação mediante:","opts":[["a","Garantias depositadas previamente pela ponta tomadora"],["b","Garantias depositadas pela ponta doadora"],["c","Aval da corretora do doador"],["d","Seguro contratado pelo emissor do ativo"]],"ans":"a","exp":"A B3 é contraparte de todos os contratos de empréstimo registrados e somente autoriza as operações com as garantias da ponta tomadora previamente depositadas.","pg":151},{"n":93,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Durante um empréstimo de ações, a companhia emissora paga dividendos. Como o doador é compensado?","opts":[["a","Perde o direito ao provento durante o empréstimo"],["b","O tomador faz ao doador um pagamento equivalente, a título de reembolso"],["c","A companhia paga o provento diretamente ao doador"],["d","A B3 paga o provento com recursos próprios"]],"ans":"b","exp":"Como o provento é creditado a quem detém os ativos na data-base (o tomador), a bolsa obriga o tomador a fazer ao doador pagamentos equivalentes de compensação, a título de reembolso.","pg":147},{"n":94,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"Quais são os prazos mínimo e máximo de uma operação a termo de ações na B3?","opts":[["a","1 e 360 dias corridos"],["b","16 e 999 dias corridos"],["c","30 e 720 dias corridos"],["d","16 e 360 dias úteis"]],"ans":"b","exp":"O prazo mínimo de uma operação a termo de ações é de 16 dias corridos, e o máximo, de 999 dias corridos.","pg":177},{"n":95,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"No mercado de opções, o prêmio é:","opts":[["a","O preço pelo qual o titular pode exercer seu direito"],["b","O valor pago pelo lançador ao titular para assumir a obrigação"],["c","O valor pago pelo titular ao lançador para ter o direito de comprar ou vender o ativo-objeto"],["d","A margem de garantia exigida do titular"]],"ans":"c","exp":"Prêmio é o valor pago pelo titular ao lançador da opção para ter o direito de comprar ou de vender o ativo-objeto.","pg":187},{"n":96,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"Considerando S o preço do ativo-objeto e K o preço de exercício, o valor intrínseco de uma opção de compra (call) é positivo quando:","opts":[["a","S > K"],["b","S < K"],["c","S = K"],["d","Sempre, independentemente de S e K"]],"ans":"a","exp":"O valor intrínseco de uma call é zero quando S ≤ K e positivo quando S > K. Na put, é positivo quando S < K.","pg":191},{"n":97,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"As opções flexíveis da B3 se caracterizam por:","opts":[["a","Serem negociadas em bolsa, com vencimentos padronizados"],["b","Serem negociadas em balcão organizado, com regras não padronizadas definidas pelas partes"],["c","Terem sempre exercício no estilo europeu e liquidação física"],["d","Serem exclusivas de investidores não residentes"]],"ans":"b","exp":"As opções flexíveis são negociadas em ambiente de balcão organizado e têm regras e funcionalidades não padronizadas, definidas a critério das partes.","pg":240},{"n":98,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"No vencimento, o contrato futuro de DI de um dia (DI1) tem PU de:","opts":[["a","1.000 pontos"],["b","10.000 pontos"],["c","100.000 pontos"],["d","1.000.000 de pontos"]],"ans":"c","exp":"No vencimento, o contrato futuro de DI1 tem PU de 100.000 pontos, sendo cada ponto igual a R$ 1,00 (R$ 100.000,00). A cotação é feita em taxa efetiva anual, base 252 dias úteis.","pg":215},{"n":99,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"O contrato futuro de Ibovespa é cotado em pontos de índice e tem vencimentos:","opts":[["a","Mensais"],["b","Bimestrais, nos meses pares"],["c","Trimestrais"],["d","Bimestrais, nos meses ímpares"]],"ans":"b","exp":"O futuro de Ibovespa é cotado em pontos de índice, e os vencimentos ocorrem bimestralmente, nos meses pares.","pg":206},{"n":100,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"Em um contrato de swap, as contrapartes:","opts":[["a","Trocam fluxos de caixa com base em prazo, valor de referência e variáveis"],["b","Trocam a propriedade dos ativos-objeto na data de início"],["c","Adquirem o direito, mas não a obrigação, de comprar um ativo"],["d","Fazem ajustes diários padronizados em bolsa"]],"ans":"a","exp":"Swap significa troca: as contrapartes trocam fluxos de caixa com base em prazo, valor de referência e variáveis.","pg":198},{"n":101,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"Debêntures que dão ao credor o direito de trocá-las por ações de OUTRA empresa, e não da emissora, são chamadas de:","opts":[["a","Simples"],["b","Conversíveis"],["c","Permutáveis"],["d","Incentivadas"]],"ans":"c","exp":"Debêntures permutáveis dão ao credor o direito de trocá-las por ações de outras empresas; nas conversíveis, a troca é por ações da própria emissora.","pg":266},{"n":102,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"A Cédula de Produto Rural (CPR), criada pela Lei nº 8.929/1994, é:","opts":[["a","Um título de crédito representativo de promessa de entrega de produtos rurais"],["b","Um título emitido por bancos com lastro em créditos do agronegócio"],["c","Um certificado emitido por securitizadora com lastro em recebíveis imobiliários"],["d","Um título público federal atrelado à inflação"]],"ans":"a","exp":"A CPR é um título de crédito representativo de promessa de entrega de produtos rurais, criado pela Lei nº 8.929/1994.","pg":267},{"n":103,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Nos fundos sujeitos ao come-cotas, o recolhimento semestral do Imposto de Renda ocorre no último dia útil de quais meses?","opts":[["a","Junho e dezembro"],["b","Março e setembro"],["c","Maio e novembro"],["d","Janeiro e julho"]],"ans":"c","exp":"O come-cotas é o recolhimento semestral de IR no último dia útil de maio e de novembro; o valor devido é abatido da quantidade de cotas do investidor.","pg":372},{"n":104,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Ficam isentos do IR os ganhos líquidos da pessoa física com ações no mercado à vista de bolsa quando o total das ALIENAÇÕES no mês não exceder:","opts":[["a","R$ 20.000,00"],["b","R$ 35.000,00"],["c","R$ 10.000,00"],["d","R$ 50.000,00"]],"ans":"a","exp":"São isentos os ganhos líquidos da pessoa física quando o total das alienações de ações no mercado à vista de bolsa no mês não exceder R$ 20.000,00.","pg":379},{"n":105,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"No day trade, quais são, respectivamente, a alíquota de IR retido na fonte e a alíquota mensal sobre os ganhos líquidos?","opts":[["a","0,005% e 15%"],["b","1% e 20%"],["c","1% e 15%"],["d","0,005% e 20%"]],"ans":"b","exp":"No day trade, a retenção na fonte é de 1% sobre o resultado positivo e o imposto mensal é de 20% sobre os ganhos líquidos.","pg":385},{"n":106,"tit":"I","titn":"Aspectos institucionais","cap":"III","capn":"A B3 no mercado financeiro e de capitais","stem":"Quantos membros compõem o Conselho de Supervisão da BSM e qual a exigência de independência?","opts":[["a","7 membros, maioria independente"],["b","9 membros, metade independente"],["c","12 membros, todos independentes"],["d","12 membros, pelo menos dois terços independentes"]],"ans":"d","exp":"O Conselho de Supervisão da BSM tem 12 membros, sendo pelo menos dois terços independentes; ele também aprova o programa de trabalho, o orçamento e o relatório de atividades da BSM.","pg":479},{"n":107,"tit":"I","titn":"Aspectos institucionais","cap":"I","capn":"Sistema Financeiro Nacional","stem":"Qual é a composição do Conselho Monetário Nacional (CMN)?","opts":[["a","Ministro da Fazenda, Ministro do Planejamento e Orçamento e Presidente do Banco Central"],["b","Presidente da República, Ministro da Fazenda e Presidente da CVM"],["c","Presidente do Banco Central, Presidente da CVM e Superintendente da Susep"],["d","Ministro da Fazenda, Presidente do Banco Central e Presidente da B3"]],"ans":"a","exp":"O CMN é composto pelo Ministro da Fazenda (presidente do Conselho), pelo Ministro do Planejamento e Orçamento e pelo Presidente do Banco Central do Brasil.","pg":22},{"n":108,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"Qual é o tamanho do contrato futuro padrão de dólar comercial (DOL) na B3?","opts":[["a","US$ 10.000,00"],["b","US$ 25.000,00"],["c","US$ 50.000,00"],["d","US$ 100.000,00"]],"ans":"c","exp":"O contrato futuro padrão de dólar comercial tem tamanho de US$ 50.000,00; o minicontrato (WDO) corresponde a US$ 10.000,00.","pg":210},{"n":109,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"O minicontrato futuro de dólar (WDO) tem tamanho de:","opts":[["a","US$ 1.000,00"],["b","US$ 5.000,00"],["c","US$ 50.000,00"],["d","US$ 10.000,00"]],"ans":"d","exp":"O minicontrato de dólar (WDO) corresponde a US$ 10.000,00, um quinto do contrato padrão de US$ 50.000,00.","pg":210},{"n":110,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"Os contratos futuros de dólar comercial (DOL e WDO) vencem:","opts":[["a","No primeiro dia útil do mês de vencimento"],["b","No último dia útil do mês anterior ao vencimento"],["c","Na quarta-feira mais próxima do dia 15 do mês de vencimento"],["d","No dia 15 do mês de vencimento ou no dia útil seguinte"]],"ans":"a","exp":"Os contratos futuros de dólar vencem no primeiro dia útil do mês de vencimento e têm liquidação exclusivamente financeira.","pg":210},{"n":111,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"I","capn":"Câmara B3","stem":"Na cadeia de salvaguardas da Câmara B3, qual é o PRIMEIRO recurso utilizado para cobrir perdas decorrentes de uma inadimplência?","opts":[["a","Recursos próprios da B3 dedicados à câmara"],["b","Garantias depositadas pelo comitente inadimplente"],["c","Contribuições dos membros de compensação adimplentes"],["d","Fundo de liquidação"]],"ans":"b","exp":"A cadeia de salvaguardas começa pelas garantias depositadas pelo próprio comitente inadimplente; só depois são usados os recursos dos intermediários, o fundo de liquidação e os recursos da B3.","pg":558},{"n":112,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"I","capn":"Câmara B3","stem":"A metodologia CORE (Close-Out Risk Evaluation), adotada pela B3, é utilizada para:","opts":[["a","Calcular os tributos devidos nas operações de bolsa"],["b","Definir o horário de abertura e fechamento do pregão"],["c","Apurar as medidas de risco da atividade de contraparte central, como as margens de garantia"],["d","Classificar as companhias nos segmentos de listagem"]],"ans":"c","exp":"A metodologia CORE foi desenvolvida para apurar as medidas de risco inerentes à atividade de contraparte central da B3 em ambientes multimercados e multiativos, como o cálculo das margens de garantia.","pg":446},{"n":113,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"Segundo o guia, o leilão especial de ativos tem duração mínima de:","opts":[["a","5 minutos"],["b","15 minutos"],["c","30 minutos"],["d","1 hora"]],"ans":"b","exp":"O guia estabelece que o leilão especial tem duração de, no mínimo, 15 minutos.","pg":527},{"n":114,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"Os túneis de negociação da B3 são mecanismos de controle que se dividem em:","opts":[["a","Túneis de alta e túneis de baixa"],["b","Túneis de abertura e túneis de fechamento"],["c","Túneis de liquidez e túneis de volatilidade"],["d","Túneis de rejeição e túneis de leilão"]],"ans":"d","exp":"Os túneis de negociação controlam as quantidades e as oscilações de preço, destacando-se os túneis de rejeição (que impedem ofertas fora dos parâmetros) e os túneis de leilão (que submetem as ofertas a leilão), além do túnel de proteção em leilões.","pg":529},{"n":115,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"O after-market é:","opts":[["a","A sessão de negociação estendida para determinados ativos e derivativos"],["b","O período de leilão que antecede a abertura do pregão"],["c","O mercado de balcão não organizado"],["d","A janela de liquidação das operações em D+2"]],"ans":"a","exp":"A sessão pode ser estendida, para determinados ativos e derivativos, por meio do after-market, que é a sessão de negociação estendida.","pg":515},{"n":116,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Pela Lei das S.A., em caso de alienação do controle, o tag along garante aos acionistas minoritários detentores de ações ordinárias o recebimento de, no mínimo:","opts":[["a","50% do preço pago por ação ao controlador"],["b","70% do preço pago por ação ao controlador"],["c","80% do preço pago por ação ao controlador"],["d","100% do preço pago por ação ao controlador"]],"ans":"c","exp":"A exigência legal prevê que os novos controladores façam oferta de compra (tag along) das ações ordinárias em poder do público, por preço igual ou superior a 80% do valor pago por ação do bloco de controle.","pg":129},{"n":117,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"V","capn":"Fundos de investimento","stem":"Para ter o tratamento tributário previsto em lei, o fundo de investimento imobiliário (FII) deve distribuir aos cotistas, no mínimo:","opts":[["a","50% do lucro auferido"],["b","75% do lucro auferido"],["c","90% do lucro auferido"],["d","95% do lucro auferido"]],"ans":"d","exp":"O FII deve distribuir a seus cotistas, no mínimo, 95% do lucro auferido.","pg":317},{"n":118,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Para que os rendimentos distribuídos por um FII sejam isentos de IR para a pessoa física, o fundo deve ter, no mínimo:","opts":[["a","50 cotistas"],["b","100 cotistas"],["c","500 cotistas"],["d","1.000 cotistas"]],"ans":"b","exp":"Entre as condições para a isenção dos rendimentos para a pessoa física está o fundo ter, no mínimo, 100 cotistas, além de limites de participação por cotista e por grupo familiar.","pg":376},{"n":119,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Para manter a isenção dos rendimentos de um FII, o cotista pessoa física pode deter, no máximo, qual percentual das cotas emitidas?","opts":[["a","10%"],["b","5%"],["c","20%"],["d","30%"]],"ans":"a","exp":"O cotista pessoa física deve ser titular de cotas que representem até 10% das cotas emitidas pelo fundo (ou que lhe deem direito a até 10% dos rendimentos).","pg":376},{"n":120,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"V","capn":"Fundos de investimento","stem":"O FIDC é um fundo no qual pelo menos qual parcela dos recursos é destinada à aquisição de direitos creditórios?","opts":[["a","25%"],["b","33%"],["c","50%"],["d","67%"]],"ans":"c","exp":"O FIDC é um tipo de fundo no qual pelo menos 50% dos recursos são destinados à aquisição de direitos creditórios.","pg":314},{"n":121,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"V","capn":"Fundos de investimento","stem":"O fundo destinado à aplicação em companhias abertas, fechadas ou sociedades limitadas em fase de desenvolvimento, com participação no processo decisório, é o:","opts":[["a","FIDC"],["b","FIP"],["c","FII"],["d","ETF"]],"ans":"b","exp":"O fundo de investimento em participações (FIP) é uma comunhão de recursos destinados à aplicação em companhias abertas, fechadas ou sociedades limitadas em fase de desenvolvimento.","pg":315},{"n":122,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"Qual é o prazo mínimo de uma Letra Financeira (LF)?","opts":[["a","90 dias"],["b","1 ano"],["c","5 anos"],["d","2 anos"]],"ans":"d","exp":"A Letra Financeira tem prazo mínimo de dois anos, vedado o resgate antecipado, total ou parcial.","pg":262},{"n":123,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"Uma Letra Financeira SEM cláusula de subordinação deve ter valor nominal unitário igual ou superior a:","opts":[["a","R$ 50.000,00"],["b","R$ 300.000,00"],["c","R$ 1.000,00"],["d","R$ 150.000,00"]],"ans":"a","exp":"A LF deve ter valor nominal unitário igual ou superior a R$ 50.000,00 se não contiver cláusula de subordinação, e a R$ 300.000,00 se contiver.","pg":262},{"n":124,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"A Letra de Crédito do Agronegócio (LCA) é:","opts":[["a","Um título emitido pelo produtor rural com promessa de entrega de produtos"],["b","Um título emitido por securitizadora com lastro em recebíveis imobiliários"],["c","Um título de crédito nominativo, de livre negociação, usado para captar recursos para a cadeia do agronegócio"],["d","Um título público federal destinado ao financiamento agrícola"]],"ans":"c","exp":"A LCA é um título de crédito nominativo, de livre negociação, utilizado para captar recursos para participantes da cadeia do agronegócio.","pg":263},{"n":125,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"As notas comerciais (commercial papers) são títulos:","opts":[["a","De longo prazo, emitidos por bancos para financiar o crédito imobiliário"],["b","De curto prazo, emitidos por sociedades não financeiras para captar recursos para capital de giro"],["c","Públicos, emitidos pelo Tesouro para financiar o déficit"],["d","De renda variável, conversíveis em ações da emissora"]],"ans":"b","exp":"Notas comerciais são títulos de curto prazo emitidos por sociedades não financeiras, com o objetivo de captar recursos para capital de giro.","pg":265},{"n":126,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Qual é a alíquota de IR sobre os rendimentos das debêntures incentivadas (Lei nº 12.431/2011) auferidos por pessoa física?","opts":[["a","15%"],["b","22,5%"],["c","0%"],["d","Tabela regressiva da renda fixa"]],"ans":"c","exp":"Nas debêntures incentivadas, os rendimentos auferidos por pessoa física estão sujeitos à alíquota de 0% de IR.","pg":364},{"n":127,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Na tabela regressiva de IR da renda fixa, qual é a alíquota para aplicações com prazo de 181 a 360 dias?","opts":[["a","22,5%"],["b","20%"],["c","17,5%"],["d","15%"]],"ans":"b","exp":"A tabela regressiva prevê 22,5% até 180 dias, 20% de 181 a 360 dias, 17,5% de 361 a 720 dias e 15% acima de 720 dias.","pg":362},{"n":128,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Um investidor resgata um CDB após 500 dias. Qual alíquota de IR se aplica ao rendimento?","opts":[["a","20%"],["b","17,5%"],["c","15%"],["d","22,5%"]],"ans":"b","exp":"Aplicações com prazo de 361 a 720 dias são tributadas a 17,5% na tabela regressiva da renda fixa.","pg":362},{"n":129,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Nos resgates de renda fixa feitos em prazo inferior a 30 dias, o IOF incide sobre o rendimento com percentual que:","opts":[["a","É fixo, de 0,38%"],["b","É fixo, de 1,5% ao mês"],["c","Varia de 96% a 0%, conforme os dias decorridos desde a aplicação"],["d","Varia de 22,5% a 15%, conforme o prazo"]],"ans":"c","exp":"O IOF incide nos resgates feitos em menos de 30 dias, com percentual que varia de 96% a 0%, conforme o número de dias decorridos desde a aplicação.","pg":387},{"n":130,"tit":"I","titn":"Aspectos institucionais","cap":"I","capn":"Sistema Financeiro Nacional","stem":"O órgão do Banco Central responsável por definir periodicamente a meta da taxa Selic é o:","opts":[["a","Conselho Monetário Nacional (CMN)"],["b","Comitê de Política Monetária (Copom)"],["c","Conselho de Recursos do Sistema Financeiro Nacional (CRSFN)"],["d","Comissão de Valores Mobiliários (CVM)"]],"ans":"b","exp":"O Copom reúne membros da diretoria do Banco Central e define periodicamente a meta da taxa Selic.","pg":231},{"n":131,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"No Tesouro Direto, o título Tesouro IPCA+ corresponde a qual título público?","opts":[["a","LTN"],["b","LFT"],["c","NTN-F"],["d","NTN-B"]],"ans":"d","exp":"O Tesouro IPCA+ corresponde à NTN-B, título indexado à inflação (IPCA); o Tesouro Prefixado corresponde à LTN e à NTN-F, e o Tesouro Selic à LFT.","pg":251},{"n":132,"tit":"VIII","titn":"Compliance","cap":"I","capn":"Prevenção à lavagem de dinheiro, ao financiamento do terrorismo e ao financiamento da proliferação de armas de destruição em massa","stem":"Segundo a Resolução CVM nº 50/2021, as operações ou propostas que apresentem sérios indícios de lavagem de dinheiro ou de financiamento do terrorismo devem ser comunicadas ao Coaf em até:","opts":[["a","48 horas após a data da operação."],["b","24 horas após a conclusão da análise que caracterizou a atipicidade."],["c","5 dias úteis após a data da operação."],["d","30 dias após o encerramento do mês da operação."]],"ans":"b","exp":"A comunicação ao Coaf deve ser feita em até 24 horas contadas da conclusão da análise que caracterizou a operação ou proposta como atípica, sem dar ciência ao cliente.","pg":641},{"n":133,"tit":"VIII","titn":"Compliance","cap":"I","capn":"Prevenção à lavagem de dinheiro, ao financiamento do terrorismo e ao financiamento da proliferação de armas de destruição em massa","stem":"Pela Resolução CVM nº 50/2021, a documentação cadastral, de monitoramento e de análise de operações relativa a PLD/FTP deve ser mantida à disposição da CVM pelo prazo mínimo de:","opts":[["a","1 ano."],["b","2 anos."],["c","5 anos."],["d","10 anos."]],"ans":"c","exp":"A documentação de cadastro, monitoramento e análise de PLD/FTP deve ser conservada por no mínimo 5 anos, à disposição da CVM.","pg":641},{"n":134,"tit":"VIII","titn":"Compliance","cap":"II","capn":"Proteção de dados pessoais e privacidade","stem":"A Lei Geral de Proteção de Dados Pessoais (LGPD) é a:","opts":[["a","Lei nº 13.709/2018, que dispõe sobre o tratamento de dados pessoais de pessoas naturais; a ANPD foi criada pela Lei nº 13.853/2019."],["b","Lei nº 12.965/2014, que criou a ANPD e regula o tratamento de dados de pessoas jurídicas."],["c","Lei nº 9.613/1998, que trata do sigilo dos dados de clientes de instituições financeiras."],["d","Lei Complementar nº 105/2001, que instituiu as bases legais para tratamento de dados pessoais."]],"ans":"a","exp":"A LGPD é a Lei nº 13.709/2018 e trata de dados pessoais de pessoas naturais. A Lei nº 13.853/2019 alterou a LGPD e criou a Autoridade Nacional de Proteção de Dados (ANPD).","pg":646},{"n":135,"tit":"VIII","titn":"Compliance","cap":"III","capn":"Adequação ao perfil do cliente (suitability)","stem":"De acordo com a Resolução CVM nº 30/2021, as instituições devem proceder a nova análise e classificação das categorias de produtos em intervalos não superiores a:","opts":[["a","6 meses."],["b","12 meses."],["c","36 meses."],["d","24 meses."]],"ans":"d","exp":"A Resolução CVM nº 30/2021 determina que a análise e a classificação das categorias de produtos sejam refeitas em intervalos não superiores a 24 meses.","pg":659},{"n":136,"tit":"IV","titn":"Gestão de risco","cap":"II","capn":"Risco corporativo e controles internos","stem":"No modelo de linhas de defesa apresentado no guia, a auditoria interna corresponde à:","opts":[["a","Primeira linha de defesa."],["b","Segunda linha de defesa."],["c","Terceira linha de defesa."],["d","Quarta linha de defesa."]],"ans":"c","exp":"A auditoria interna é a terceira linha de defesa: avalia de forma independente a efetividade da gestão de riscos e dos controles. A primeira é a gestão operacional, a segunda são controles internos/riscos/compliance e a quarta, auditoria externa e reguladores.","pg":464},{"n":137,"tit":"IV","titn":"Gestão de risco","cap":"II","capn":"Risco corporativo e controles internos","stem":"A norma que exige das instituições autorizadas pelo Banco Central a implementação de estrutura de gerenciamento de riscos (crédito, mercado, operacional e liquidez) e a indicação de diretor responsável (CRO) é a:","opts":[["a","Resolução CMN nº 4.557/2017."],["b","Resolução CVM nº 30/2021."],["c","Resolução CMN nº 4.945/2021."],["d","Resolução CVM nº 50/2021."]],"ans":"a","exp":"A Resolução CMN nº 4.557/2017 dispõe sobre a estrutura de gerenciamento de riscos e de capital e exige a indicação de diretor responsável pelo gerenciamento de riscos (CRO).","pg":470},{"n":138,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"I","capn":"Cadastro de investidores residentes","stem":"O sistema da B3 utilizado para inclusão e manutenção dos dados cadastrais de comitentes, contas, vínculos e profissionais é o:","opts":[["a","RDE."],["b","Sincad."],["c","Sisbacen."],["d","CORE."]],"ans":"b","exp":"O Sincad (Sistema Integrado de Cadastro) é a plataforma da B3 para inclusão e manutenção de dados de comitentes, contas, vínculos e profissionais.","pg":401},{"n":139,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"I","capn":"Cadastro de investidores residentes","stem":"A conta máster é uma estrutura de conta:","opts":[["a","de depósito definitiva, na qual os ativos do comitente ficam custodiados."],["b","exclusiva de investidores não residentes, aberta pelo representante legal."],["c","transitória, que agrupa ordens de comitentes com vínculo comum para posterior alocação aos beneficiários finais."],["d","de garantia, utilizada para depósito de margem junto à Câmara B3."]],"ans":"c","exp":"A conta máster é transitória: agrupa ordens de comitentes que possuem vínculo comum, e as operações são depois alocadas às contas dos beneficiários finais.","pg":404},{"n":140,"tit":"VII","titn":"Central depositária","cap":"I","capn":"Central depositária da B3","stem":"Em relação aos ativos mantidos sob guarda na central depositária da B3, é correto afirmar que:","opts":[["a","integram o patrimônio da B3 até a liquidação das operações."],["b","podem ser usados pela B3 para cobrir perdas de qualquer participante."],["c","pertencem ao agente de custódia enquanto estiverem depositados."],["d","não integram o patrimônio da B3 e permanecem em nome dos comitentes."]],"ans":"d","exp":"Os ativos depositados na central depositária não integram o patrimônio da B3: ficam segregados e mantidos em nome dos respectivos comitentes (titulares).","pg":604},{"n":141,"tit":"VII","titn":"Central depositária","cap":"II","capn":"Processos operacionais da central depositária da B3","stem":"O controle de saldos que registra, além da quantidade, as datas e os custos de aquisição dos ativos, permitindo a apuração tributária, é chamado de controle:","opts":[["a","analítico."],["b","sintético."],["c","fungível."],["d","consolidado."]],"ans":"a","exp":"No controle analítico são registradas as datas e os custos de aquisição, o que permite a apuração tributária. O controle sintético registra apenas a quantidade consolidada.","pg":619}],K="simuladoB3v2",S=null,warned=false;
var WHY={4: {"b": "Best execution é a obrigação de buscar o melhor resultado possível na execução da ordem do cliente, não o sistema de registro eletrônico de ativos.", "c": "Electronic shares é uma expressão genérica para ações em ambiente eletrônico e não o nome técnico do sistema de transferência e liquidação por registros.", "d": "Uncertificated shares são ações sem certificado físico. O conceito trata da forma do ativo, não do sistema de liquidação."}, 5: {"a": "Book entry é o registro e a transferência escritural de ativos. Não é a regra de execução de ordens nas melhores condições para o cliente.", "c": "Electronic shares descreve ações negociadas ou mantidas eletronicamente, mas não o dever do intermediário de buscar o melhor resultado.", "d": "Uncertificated shares são ações sem certificado físico e não um regime para prevenir conflitos na execução de ordens."}, 6: {"a": "Desmaterialização é a substituição de documentos ou certificados físicos por registros eletrônicos. Não altera as contrapartes do contrato.", "b": "Liquidação diferida indica que a liquidação ocorre em data posterior à negociação. Não transforma a câmara em compradora e vendedora das operações.", "d": "Liquidação bruta processa cada obrigação individualmente, sem compensação líquida. Não é o processo de substituição das contrapartes originais."}, 40: {"b": "Risco de crédito é a possibilidade de a contraparte não cumprir uma obrigação. A questão trata de perda causada pela oscilação de preços.", "c": "Risco de liquidez é a dificuldade de negociar um ativo ou obter recursos sem perda relevante. Não é a variação do valor de mercado.", "d": "Risco operacional decorre de falhas em processos, pessoas, sistemas ou eventos externos, e não da oscilação de preços."}, 41: {"a": "O PNP acessa diretamente a negociação, mas a relação da B3 como contraparte central na liquidação ocorre perante o membro de compensação.", "b": "O PL pode liquidar operações sem exercer necessariamente a função de membro de compensação perante a contraparte central.", "d": "O comitente é o cliente final. A B3 não assume diretamente perante o comitente a posição de contraparte central."}, 42: {"a": "Survivor pays utiliza recursos mutualizados dos participantes adimplentes para cobrir a inadimplência de outro participante.", "c": "Third parties pay sugeriria uso de recursos de terceiros e não é a denominação da salvaguarda vinculada ao próprio inadimplente.", "d": "Modelo integrado descreve a arquitetura de risco e pós-negociação, não a regra de uso exclusivo dos recursos do participante inadimplente."}, 43: {"a": "“Introdutória” não é uma linha reconhecida no modelo das três linhas.", "c": "A segunda linha reúne funções de risco, compliance e controles que monitoram e orientam a gestão operacional.", "d": "A terceira linha corresponde à auditoria interna, que fornece avaliação independente sobre governança, riscos e controles."}, 44: {"a": "A área dona do risco e responsável por operar os controles integra a primeira linha de defesa.", "b": "A auditoria interna desempenha a terceira linha de defesa, com avaliação independente.", "c": "Investigar se um risco já se materializou pode fazer parte de apurações, mas não define a função principal da segunda linha."}, 45: {"b": "Front running é negociar antecipadamente usando conhecimento de ordem relevante de cliente que ainda será executada.", "c": "Insider trading é negociar com informação relevante ainda não divulgada ao mercado.", "d": "Framing não é o termo técnico usado para o giro excessivo da carteira com objetivo de gerar corretagem."}, 64: {"b": "A condição de PEP exige abordagem baseada em risco e diligência reforçada. Tratar exatamente como os demais ignora esse risco adicional.", "c": "Ser PEP não implica recusa automática de cadastro. A instituição deve avaliar e controlar o risco.", "d": "Nem toda operação de PEP é comunicada ao Coaf. A comunicação depende dos critérios de suspeição e das regras aplicáveis."}, 65: {"b": "O período indicado pelo material é de 12 meses, não 18 meses.", "c": "O conceito não se limita à movimentação em conta-corrente; também abrange custódia, operações e existência de saldo.", "d": "Além de usar prazo incorreto, a alternativa restringe indevidamente a atividade a operações de day trade."}, 66: {"b": "Conglomerados devem possuir mecanismos de intercâmbio de informações. A vedação desse intercâmbio prejudicaria a aplicação integrada da política.", "c": "A política deve ser formalizada, aprovada e atualizada. Seu conteúdo não pode ser tratado apenas como documento confidencial sem governança.", "d": "A aprovação cabe à alta administração da instituição, e não previamente ao Bacen, à CVM ou ao Coaf."}, 67: {"a": "O compliance officer atua na conformidade de forma ampla, mas a função específica de canal sobre proteção de dados pertence ao encarregado/DPO.", "b": "Marketing e comunicação não exercem, por definição, as atribuições legais do encarregado de dados.", "d": "A diretoria de RH pode tratar dados pessoais de empregados, mas não é automaticamente o canal institucional previsto para proteção de dados."}, 68: {"a": "O direito de exclusão não é absoluto. Obrigações legais, regulatórias ou outros direitos podem justificar a conservação.", "b": "A empresa deve explicar e fundamentar a impossibilidade de excluir; não basta negar sem justificativa.", "d": "A exclusão é um direito que pode ser solicitado pelo titular, sujeito às hipóteses legais de conservação."}, 69: {"a": "A LGPD prevê diversas bases legais além do consentimento, como obrigação legal, execução de contrato e legítimo interesse.", "b": "O consentimento pode ser revogado pelo titular, observadas as consequências e os tratamentos já realizados de forma legítima.", "d": "No mercado financeiro muitos tratamentos se apoiam em obrigação legal, contrato ou prevenção à fraude, portanto o consentimento não é sempre indispensável."}, 70: {"a": "A divergência de perfil não gera recusa automática. O participante deve alertar o cliente e observar os procedimentos regulatórios.", "b": "Uma ordem desenquadrada do perfil não é, por si só, situação de comunicação ao Coaf ou à CVM.", "c": "Executar sem advertência deixa de informar ao investidor a inadequação identificada pelo suitability."}, 71: {"a": "Investidor de varejo é a categoria geral e não reflete a condição especial obtida com mais de R$ 1 milhão e declaração própria.", "c": "“Investidor institucional” não é a classificação atribuída à pessoa natural apenas pelo valor informado.", "d": "Para investidor profissional, o limite patrimonial aplicável é superior ao de investidor qualificado e segue requisitos próprios."}, 72: {"b": "O objetivo do cliente integra obrigatoriamente a análise de adequação. Ignorá-lo compromete o suitability.", "c": "O objetivo não é o único critério; situação financeira e conhecimento/experiência também devem ser avaliados.", "d": "Não há um único critério universalmente mais importante. A adequação resulta da análise conjunta das informações do cliente."}, 73: {"a": "Spoofing usa ofertas sem intenção real de execução para induzir o mercado. Não é giro excessivo para gerar comissão.", "b": "Layering cria múltiplas camadas de ofertas artificiais para influenciar o livro. Não descreve a negociação excessiva da carteira.", "d": "OMC e front running são práticas distintas: OMC envolve condições artificiais e front running usa conhecimento prévio de ordens. Nenhuma define giro para gerar comissão."}, 74: {"b": "Front running usa informação sobre ordem pendente; layering utiliza várias camadas de ofertas. A descrição aponta especificamente para uma oferta falsa no spoofing.", "c": "Churning é o giro excessivo da carteira para gerar comissões.", "d": "Operação em condições artificiais é categoria mais ampla e não é o nome específico da conduta descrita."}, 75: {"a": "A responsabilização não se limita ao investidor, pois o participante também possui deveres de supervisão e controle.", "b": "A conduta pode partir do investidor, portanto a punição não se restringe ao participante de mercado.", "d": "A alternativa restringe a responsabilização ao diretor do participante; o participante de mercado também pode ser responsabilizado como instituição."}, 76: {"a": "O Bacen disciplina instituições sob sua supervisão, mas o sistema de distribuição de valores mobiliários também está sujeito às regras da CVM.", "b": "A CVM disciplina o mercado de valores mobiliários, mas as instituições financeiras também seguem regras de segurança cibernética do Bacen.", "d": "A ANPD fiscaliza proteção de dados pessoais, mas não é indicada como emissora conjunta dessas regras prudenciais do sistema de distribuição."}, 77: {"a": "Não existe modelo único do Bacen aplicável indistintamente; a política deve ser proporcional às características da instituição.", "b": "A CVM estabelece requisitos, mas não um modelo padrão único para todas as instituições.", "d": "Capital social e perfil de clientes podem ser elementos de contexto, porém a formulação exigida considera porte, perfil e modelo de negócio."}, 78: {"a": "A escolha não é totalmente livre; deve atender aos requisitos regulatórios de contratação e supervisão do serviço.", "b": "O material não exige homologação individual do prestador pelo Bacen.", "d": "Não há, para esse requisito, lista anual de prestadores divulgada pelo Bacen."}, 79: {"b": "A PRSAC não é definida por riscos socioeconômico e operacional; a norma separa as naturezas social, ambiental e climática.", "c": "Risco demográfico não substitui o risco climático previsto na política.", "d": "Riscos socioeconômico e geopolítico não formam o trio regulatório da PRSAC."}, 80: {"a": "A política não precisa ser necessariamente segregada por instituição; pode haver documento unificado no conglomerado.", "b": "Pode existir política única, mas ela não pode ignorar as particularidades de cada instituição.", "c": "Tratar apenas aspectos comuns é insuficiente, pois a política unificada deve contemplar as características específicas de cada integrante."}, 81: {"a": "O prazo apresentado no material é de 5 anos, não 10 anos.", "b": "A documentação deve ficar disponível ao Banco Central, e não ao Ministério do Meio Ambiente.", "d": "O órgão está correto, mas o prazo é de 5 anos, não 10 anos."}};
var WHY2={"1": {"b": "A Lei nº 6.385/1976 criou a CVM e disciplinou o mercado de valores mobiliários; não foi ela que estabeleceu os pilares do SFN.", "c": "A Lei nº 6.404/1976 é a Lei das Sociedades por Ações; trata da organização das companhias, não da estrutura do SFN.", "d": "A Lei nº 4.728/1965 é a Lei do Mercado de Capitais. Os pilares do SFN, com a criação do CMN e do Bacen, vieram da Lei nº 4.595/1964."}, "2": {"a": "O mercado de crédito atende às necessidades de financiamento de pessoas e empresas por meio de instituições financeiras; não é o mercado de controle da liquidez da economia.", "c": "O mercado de capitais financia investimentos de médio e longo prazo das empresas (ações, debêntures etc.), e não o controle da oferta de moeda.", "d": "O mercado de câmbio reúne as operações de compra e venda de moeda estrangeira, e não as operações de controle de moeda e juros de curto prazo."}, "3": {"a": "O Bacen supervisiona as instituições financeiras e executa a política monetária, mas não supervisiona a previdência complementar aberta.", "b": "A CVM regula e fiscaliza o mercado de valores mobiliários; seguros e previdência aberta ficam com a Susep.", "d": "A Previc supervisiona as entidades fechadas de previdência complementar (fundos de pensão), não os planos de previdência aberta."}, "7": {"a": "A câmara de compensação calcula e liquida as obrigações das operações; a guarda dos ativos e a proteção da titularidade cabem à central depositária.", "b": "A central de registro registra ativos e operações, principalmente de balcão, mas a guarda centralizada que protege a propriedade dos ativos é função da central depositária.", "c": "A Câmara de Câmbio liquida operações interbancárias de câmbio; não faz a guarda de ativos."}, "8": {"a": "O membro de compensação responde perante a câmara pela liquidação das operações; não é o canal de acesso direto ao sistema de negociação.", "c": "O participante de liquidação atua na liquidação das operações perante o membro de compensação; não dá acesso direto à negociação.", "d": "Banco de investimento é um tipo de instituição financeira, e não uma categoria de acesso ao sistema de negociação da B3."}, "9": {"a": "A BSM é a entidade que administra o mecanismo, mas não é o nome do mecanismo de ressarcimento.", "c": "PAD é o Processo Administrativo Disciplinar, instaurado pela BSM para apurar infrações e aplicar sanções; não é o mecanismo de ressarcimento de prejuízos.", "d": "RPB3 não é o nome de nenhum mecanismo previsto no guia; o mecanismo correto é o MRP – Mecanismo de Ressarcimento de Prejuízos."}, "10": {"b": "Rendimentos fixos são típicos da renda fixa; a ação não paga remuneração fixa predeterminada ao acionista.", "c": "“Rendimentos variáveis” é uma expressão genérica, não uma forma de remuneração deliberada e paga pela companhia.", "d": "O ganho de capital vem da valorização da ação, realizada pelo investidor na venda; não é um pagamento feito pela empresa."}, "11": {"a": "Ponderar por pesos iguais significa dar o mesmo peso a todas as ações, o que não corresponde ao critério do Ibovespa apresentado no guia.", "b": "O gabarito do guia indica “ponderado por liquidez”. Atenção: na descrição da metodologia, o guia explica que os ativos são ponderados pelo valor de mercado do free float, com limite de participação baseado na liquidez — por isso a capitalização de mercado pura não é a resposta esperada.", "c": "“Pesos diferenciados” é uma expressão genérica que não identifica o critério de ponderação do índice."}, "12": {"a": "O envolvimento da emissora estrangeira caracteriza os programas patrocinados; no BDR Não Patrocinado a iniciativa é apenas da instituição depositária.", "c": "Bolsas estrangeiras não participam dessa decisão; quem solicita o registro à CVM e à B3 é a instituição depositária no Brasil.", "d": "A alternativa fala da origem das empresas e não responde ao ponto da questão: no BDR NP N1 a emissora estrangeira não se envolve."}, "13": {"a": "O contrato futuro de moedas é negociado em bolsa, é padronizado e tem ajustes diários; o enunciado descreve uma operação de balcão.", "c": "O contrato futuro de dólar também é negociado em bolsa, com ajustes diários, e não em balcão com taxa travada até o vencimento.", "d": "O termo de mercadorias tem como objeto commodities, e não a taxa de câmbio entre duas moedas."}, "14": {"a": "Falta o arbitrador, que busca lucro explorando distorções de preço entre mercados ou vencimentos.", "b": "Falta o especulador, que assume risco em busca de lucro com a variação de preços e traz liquidez ao mercado.", "d": "Falta o hedger, que usa derivativos para se proteger do risco de variação de preços."}, "15": {"a": "O cupom limpo usa a taxa de câmbio do próprio dia de início do período; o DDI negocia o cupom sujo, que usa a PTAX do dia útil anterior.", "b": "“Cupom sintético” não é o nome do cupom negociado no contrato futuro de DDI.", "c": "O cupom cambial a termo (limpo) é negociado pelo FRA de cupom (FRC), que combina dois contratos de DDI com posições opostas; o DDI isolado negocia o cupom sujo."}, "16": {"a": "O Selic é o sistema do Bacen para custódia e liquidação de títulos públicos federais (e também o nome da taxa básica de juros); não é o programa de venda direta a pessoas físicas.", "c": "A Cetip foi a depositária e registradora de ativos de balcão que se integrou à B3; não é o programa do Tesouro para pessoas físicas.", "d": "O Puma é a plataforma de negociação da B3 (Puma Trading System), e não o programa de venda de títulos públicos a pessoas físicas."}, "17": {"a": "A última lacuna está errada: quanto maior a duration, maior (e não menor) a exposição ao risco.", "c": "A segunda lacuna está errada: quanto maior a duration, maior (e não menor) o tempo para recuperar o valor investido.", "d": "A segunda e a terceira lacunas estão erradas: tempo de recuperação e exposição ao risco aumentam junto com a duration."}, "18": {"a": "O CRI tem lastro em recebíveis imobiliários, e não em recebíveis do agronegócio.", "b": "O CDB é um título de captação bancária e não tem lastro em recebíveis do agronegócio.", "c": "A LTN é um título público federal prefixado emitido pelo Tesouro Nacional, sem lastro em recebíveis."}, "19": {"a": "A alternativa omite a liquidação em D+2, que também é permitida.", "b": "A alternativa omite a liquidação em D+0 (no mesmo dia), que também é permitida.", "d": "A alternativa restringe a liquidação a D+0, mas as partes também podem escolher D+1 ou D+2."}, "20": {"b": "O Sisbex era o antigo sistema eletrônico de negociação de títulos públicos, substituído pelo Puma Trading System; não é a plataforma de dólar pronto.", "c": "O BovespaFix era o antigo sistema eletrônico de negociação de títulos privados de renda fixa, também substituído pelo Puma Trading System.", "d": "Tradenet não é a plataforma eletrônica da B3 para negociar dólar pronto."}, "21": {"b": "PCAM não é o nome da taxa de referência calculada pelo Bacen a partir das consultas diárias ao mercado.", "c": "A Reuters é uma provedora de informações de mercado, e não a taxa de referência calculada pelo Banco Central.", "d": "“Taxa B3” não designa a taxa média de câmbio; a PTAX é calculada e divulgada pelo Banco Central."}, "22": {"a": "O valor de emissão é o preço pelo qual as cotas são emitidas em um dado momento, e não a fração do patrimônio em si.", "c": "O valor financeiro é o montante em reais aplicado ou resgatado (quantidade × valor da cota).", "d": "A quantidade indica quantas cotas o investidor tem, e não a fração do patrimônio do fundo."}, "23": {"a": "Nos fundos fechados as cotas só são resgatadas ao fim do prazo de duração; antes disso, a saída é pela venda no mercado secundário.", "b": "Fundos exclusivos são definidos pelo público (um único cotista), e não pelo regime de aplicações e resgates.", "d": "“Ativo” se refere à estratégia de gestão (buscar superar um índice de referência), e não ao regime de aplicações e resgates."}, "24": {"a": "O fundo de renda fixa é classificado pela composição da carteira e, em geral, não tem cotas negociadas em bolsa que repliquem um índice.", "b": "O fundo de ações investe principalmente em ações, mas não necessariamente replica um índice nem tem cotas negociadas em bolsa.", "c": "O fundo imobiliário tem cotas negociadas em bolsa, mas investe em ativos imobiliários e não replica um índice."}, "25": {"a": "O valor de emissão é o preço pelo qual as cotas do clube são emitidas, e não a fração do patrimônio.", "c": "O valor financeiro é o montante em reais aplicado ou resgatado, e não a fração do patrimônio do clube.", "d": "A quantidade indica quantas cotas o participante tem, e não a fração do patrimônio do clube."}, "26": {"b": "A CVM regula os clubes de investimento, mas o registro é feito na B3.", "c": "O Bacen não tem atribuição sobre o registro de clubes de investimento.", "d": "A BSM atua na autorregulação e supervisão, mas não é a entidade responsável pelo registro dos clubes."}, "27": {"a": "A distribuição de cotas de clube por meios públicos de comunicação não é permitida; o guia trata essa prática como vedada.", "c": "Não há ressalvas que autorizem esse tipo de distribuição: a vedação abrange imprensa, rádio, TV, páginas abertas na internet e malas diretas.", "d": "A vedação não é parcial nem tem ressalvas; a distribuição por esses meios é simplesmente vedada."}, "28": {"b": "A LIG (Letra Imobiliária Garantida) é um título de renda fixa lastreado em créditos imobiliários, com carteira de ativos em patrimônio separado da emissora (inspirada nos covered bonds); não é a versão brasileira das notas estruturadas.", "c": "Vendor é a empresa que distribui informações de mercado, e não um produto de investimento.", "d": "O CDB é um título de captação bancária, sem a estrutura com derivativos embutidos típica das notas estruturadas."}, "29": {"a": "A União não emite Cepac; o instrumento é municipal e ligado ao planejamento urbano.", "c": "Os estados não emitem Cepac; as operações urbanas consorciadas são municipais.", "d": "As empresas não emitem Cepac; elas podem comprá-los para obter o direito de construir além do limite básico."}, "30": {"a": "Vendor é a empresa que redistribui as informações da bolsa aos usuários finais, e não o serviço da B3 que as gera e envia.", "b": "A gestão de garantias trata do controle dos colaterais depositados pelos participantes, e não da difusão de informações.", "d": "O Cepac é um valor mobiliário municipal ligado a direitos de construção, e não um serviço de informações."}, "31": {"b": "A ordem está invertida: primeiro se calcula o IOF, que é deduzido do rendimento, e depois incide o IR.", "c": "Também há incidência de Imposto de Renda; o prazo curto não isenta do IR.", "d": "Em prazos inferiores a 30 dias também incide o IOF, cobrado antes do IR."}, "32": {"a": "A poupança é isenta, mas o CDB é tributado pela tabela regressiva do IR.", "b": "O CDB é tributado pelo IR, o que torna a alternativa incorreta.", "d": "A LCI é isenta para pessoa física, mas o CDB é tributado pelo IR."}, "33": {"b": "Investidores domiciliados em paraísos fiscais não têm acesso ao regime especial; seguem as mesmas regras aplicáveis aos residentes no Brasil.", "c": "A alternativa inclui indevidamente os domiciliados em paraísos fiscais, que não têm acesso ao regime especial.", "d": "Os residentes seguem o regime geral de tributação; o regime especial vale apenas para não residentes fora de paraísos fiscais."}, "34": {"a": "A corretora é intermediária; a estrutura de contas deve identificar o titular final dos ativos, e não o intermediário.", "b": "O banco custodiante presta o serviço de custódia, mas as contas devem estar em nome do beneficiário final.", "d": "O sistema de custódia é infraestrutura, e não titular dos ativos; as contas ficam em nome do beneficiário final."}, "35": {"b": "A identificação é do investidor (comitente final), e não da corretora que intermedia a operação.", "c": "A identificação deve ocorrer quando a operação é realizada, e não depois, na liquidação.", "d": "A regra exige identificar o investidor na própria operação, e não apenas no momento do registro na conta máster."}, "36": {"a": "A alternativa omite a possibilidade de repasse entre um PNP e um PL.", "b": "A alternativa omite a exigência de vínculo de repasse entre as partes.", "c": "A alternativa omite a possibilidade de repasse entre PNP e PL e a exigência de contrato específico."}, "37": {"a": "“Residentes e domiciliados” deixa de fora os investidores não residentes, que também são abrangidos pelas normas.", "c": "A alternativa deixa de fora os investidores residentes, que também estão sujeitos às normas de cadastro.", "d": "A categoria correta é “residentes e não residentes”; “residentes não domiciliados” não é a classificação usada."}, "38": {"b": "A resolução não restringe o acesso a mercados específicos; ela dá acesso aos mesmos mercados disponíveis ao residente.", "c": "Não há restrição ao mercado de juros; o acesso é aos mesmos mercados do investidor residente.", "d": "Não há restrição ao mercado de ações; o acesso é aos mesmos mercados do investidor residente."}, "39": {"a": "O representante fiscal cuida dos assuntos tributários do investidor perante as autoridades brasileiras; quem faz o registro na CVM é o representante legal.", "c": "O custodiante guarda e controla os ativos e mantém a documentação atualizada, mas não é quem faz o registro na CVM.", "d": "O investidor não residente atua por meio de representante no país; não faz o registro diretamente."}, "46": {"a": "Contradiz o estilo americano, que permite o exercício a qualquer tempo até o vencimento.", "c": "Exercício apenas na data de vencimento caracteriza a opção de estilo europeu.", "d": "D+2 é um prazo de liquidação, e não a regra de exercício da opção americana."}, "47": {"a": "Omite a data de vencimento e o tipo de liquidação; além disso, “quantidade máxima” não está entre as características padronizadas citadas.", "b": "Omite a cotação e restringe a “liquidação bruta”, quando o tipo de liquidação é uma característica definida pela bolsa para cada contrato.", "c": "Nos contratos futuros os vencimentos são padronizados pela bolsa; “qualquer data” é característica de operações a termo ou de balcão."}, "48": {"a": "A opção não envolve empréstimo de ativos; o lançador de put assume a obrigação de comprar.", "c": "Vender ao titular é a obrigação do lançador de uma opção de compra (call), e não de venda.", "d": "O lançador recebe o prêmio e, por isso, assume a obrigação de comprar o ativo se a opção for exercida."}, "49": {"a": "A B3 administra os mercados, mas apurar e punir as infrações do Regulamento de Negociação cabe à BSM, sua autorreguladora.", "c": "A CVM pune no âmbito de sua competência legal, mas o enunciado trata do Regulamento de Negociação da B3 e das penalidades do estatuto e do regulamento processual da BSM.", "d": "O Bacen não é responsável por apurar infrações ao Regulamento de Negociação da B3."}, "50": {"b": "After-hours é um período de negociação após o pregão regular, e não um mecanismo de interrupção.", "c": "Co-location é o serviço de hospedar servidores no data center da bolsa para reduzir latência.", "d": "STP (straight-through processing) é o processamento automático de ponta a ponta, sem intervenção manual."}, "51": {"a": "O PNP tem acesso direto ao ambiente de negociação e transmite ordens; é intermediário, e não o cliente cujas ordens são transmitidas.", "b": "O PN é um intermediário que atua por meio de um PNP; não é o cliente final.", "d": "O formador de mercado é contratado para manter ofertas de compra e venda e dar liquidez; não é o comitente."}, "52": {"a": "O participante de liquidação responde pela liquidação de suas operações e de seus clientes, mas não é ele quem movimenta a conta reservas junto à câmara.", "c": "O participante de negociação negocia em nome dos clientes, mas não movimenta conta reservas bancárias com a câmara.", "d": "O membro de compensação liquida o saldo com a câmara, mas os pagamentos são efetuados pela conta reservas bancárias (ou conta de liquidação) do liquidante."}, "53": {"a": "O comitente é o cliente final; a câmara não assume posição de contraparte central diretamente perante ele.", "b": "O participante de negociação não é contraparte direta da câmara na liquidação.", "c": "O participante de liquidação atua na compensação e liquidação por meio de um membro de compensação; a câmara é contraparte central exclusivamente perante o membro de compensação."}, "54": {"a": "Insolvência é uma situação patrimonial mais ampla (incapacidade de pagar as dívidas em geral), e não o termo usado pela câmara para falha de liquidação.", "b": "A concordata era um instituto da antiga lei de falências, substituído pela recuperação judicial, e não se aplica a esse caso.", "d": "Devedor operacional é a classificação de quem deixa de liquidar por motivo operacional. Quando a falha decorre de insuficiência financeira, como no enunciado, o participante pode ser declarado inadimplente."}, "55": {"b": "Swing trade é a estratégia de manter posições por alguns dias, e não comprar e vender no mesmo dia.", "c": "Front runner é quem pratica front running, conduta ilícita de antecipar-se a ordens de clientes.", "d": "Spot significa mercado à vista, e não a combinação de compra e venda no mesmo dia."}, "56": {"a": "A alternativa omite a modalidade com garantia parcial.", "c": "Restringir a operações sem garantia está errado: também existem as modalidades com garantia e com garantia parcial.", "d": "Restringir a operações com garantia está errado: também existem as modalidades sem garantia e com garantia parcial."}, "57": {"a": "Na modalidade com garantia (total), a câmara atua como contraparte central de ambas as partes e garante a liquidação.", "b": "Na modalidade com garantia parcial, a câmara atua como contraparte central de apenas uma das partes (por exemplo, em swaps); portanto, não se limita a operacionalizar a liquidação.", "c": "“Sem garantia parcial” não é uma modalidade prevista para as operações registradas."}, "58": {"a": "Comunicados divulgam avisos e informações ao mercado, mas a política de tarifação é divulgada por ofício circular.", "c": "Informes ao mercado não são o instrumento usado para divulgar a política de tarifação da B3.", "d": "Os membros de compensação não divulgam a política de tarifação da B3; ela é publicada pela própria B3 por ofício circular."}, "59": {"b": "A política de tarifação trata dos custos e encargos cobrados, e não da continuidade das atividades em caso de desastre.", "c": "“Política de processamento de dados” não é o documento que garante a continuidade das atividades.", "d": "A unidade de contingência externa é um dos recursos previstos, mas o documento citado no guia é a política de continuidade de negócios."}, "60": {"a": "Sistema externo é uma infraestrutura de mercado (sistema de negociação, câmara ou central depositária) autorizada a se conectar à B3, e não o participante com acesso para custódia.", "b": "O emissor é quem emite os ativos, e não quem tem autorização de acesso para custódia.", "c": "O escriturador é contratado pelo emissor para manter os registros dos ativos escriturais, mas não é o participante com autorização de acesso para custódia na central depositária."}, "61": {"a": "“Serviço de Atendimento ao Investidor” não é o nome do serviço oferecido pela central depositária no site.", "c": "“Consulta de Participantes” não é o nome do serviço citado no guia.", "d": "As consultas de posição e movimentação ficam dentro da Área do Investidor; “Extrato Eletrônico” não é o nome do serviço."}, "62": {"a": "A alternativa omite o comitente: as contas são identificadas por agente de custódia e por comitente.", "b": "A alternativa omite o agente de custódia: as contas são identificadas por agente de custódia e por comitente.", "d": "“Conta de ativos” não é critério de identificação; as contas são divididas em carteiras, e não numeradas por ativo."}, "63": {"b": "“Digital” não é o termo técnico usado; o controle dos saldos é feito em forma escritural.", "c": "A guarda centralizada é desmaterializada, por registros eletrônicos, e não física.", "d": "A fungibilidade é uma característica dos ativos custodiados, e não a forma de controle dos saldos."}};Object.keys(WHY2).forEach(function(k){WHY[k]=WHY[k]||{};Object.keys(WHY2[k]).forEach(function(l){WHY[k][l]=WHY2[k][l]})});
var WHY3={"82": {"a": "25% não é o limite legal; a lei exige no mínimo 50% de ações ordinárias.", "b": "Um terço não é o limite da Lei das S.A.; o mínimo de ações ordinárias é 50% do capital.", "d": "Dois terços não é o critério legal; a exigência é de no mínimo 50% de ordinárias."}, "83": {"b": "O free float de 20% (ou regra alternativa) também se aplica ao Nível 1; não é exclusivo do Novo Mercado.", "c": "Manter ações preferenciais é característica do Nível 2; o Novo Mercado só admite ações ordinárias.", "d": "A listagem sem oferta, com até sete anos para o IPO, é característica do Bovespa Mais."}, "84": {"a": "O Novo Mercado é o segmento de mais alto padrão de governança, com capital só em ações ordinárias; não prevê listagem sem oferta.", "b": "O Nível 2 se caracteriza por permitir ações preferenciais com tag along de 100%, e não pela listagem sem oferta.", "c": "O Nível 1 exige práticas de transparência e free float mínimo, mas não prevê listagem sem oferta com prazo para o IPO."}, "85": {"a": "Na subscrição o acionista tem preferência para adquirir novas ações, pagando por elas; não é distribuição gratuita.", "c": "O desdobramento divide as ações existentes, sem aumento de capital nem incorporação de reservas.", "d": "Juros sobre capital próprio são remuneração em dinheiro, e não a entrega de novas ações."}, "86": {"b": "O desdobramento (split) divide cada ação em várias, ou seja, faz o movimento contrário ao descrito.", "c": "A bonificação distribui novas ações gratuitamente, aumentando a quantidade em poder do acionista.", "d": "A subscrição é a aquisição de novas ações em aumento de capital, mediante pagamento."}, "87": {"a": "A ordem a mercado especifica só a quantidade e as características do ativo e é executada assim que recebida, sem limite de preço.", "b": "Na ordem administrada a execução fica a critério do PNP ou do PN, sem preço fixado pelo cliente.", "d": "A ordem casada é vinculada à execução de outra ordem do cliente; o limite de preço não é sua característica definidora."}, "88": {"a": "A ordem stop especifica o preço a partir do qual a ordem deverá ser executada.", "c": "A ordem limitada fixa o preço máximo (compra) ou mínimo (venda) para a execução.", "d": "A ordem casada depende da execução de outra ordem do cliente."}, "89": {"b": "Ofertas on close (MOC/LOC) são direcionadas ao call de fechamento, e não vinculadas a outra ordem.", "c": "A ordem stop é disparada quando o preço do ativo atinge o nível especificado.", "d": "Na ordem administrada a execução fica a critério do intermediário, sem vínculo com outra ordem."}, "90": {"a": "15 minutos não é o prazo previsto; na queda de 10% a interrupção é de 30 minutos.", "c": "A interrupção de 1 hora ocorre quando a queda atinge 15%, após a reabertura.", "d": "A suspensão por prazo definido pela B3 vale para a queda de 20%."}, "91": {"a": "30 minutos é a interrupção correspondente à queda de 10%.", "b": "Não há interrupção de 2 horas na regra do circuit breaker.", "d": "A suspensão por prazo definido pela B3 só se aplica à queda de 20%; não há regra automática até o fim do pregão na queda de 15%."}, "92": {"b": "O doador entrega os ativos; quem deposita garantias é o tomador, que assume a obrigação de devolvê-los.", "c": "O aval de corretora não é o requisito previsto; a exigência é de garantias do tomador depositadas na B3.", "d": "O emissor não participa do empréstimo nem contrata seguro para essas operações."}, "93": {"a": "O doador não perde os proventos: o tomador é obrigado a reembolsá-lo.", "c": "A companhia credita o provento a quem detém o ativo na data-base, que é o tomador.", "d": "A B3 não paga proventos com recursos próprios; a compensação é feita pelo tomador."}, "94": {"a": "O prazo mínimo é de 16 dias corridos, e não de 1 dia; o máximo é de 999 dias.", "c": "Os limites corretos são 16 e 999 dias corridos.", "d": "Os prazos são contados em dias corridos, e o máximo é de 999 dias."}, "95": {"a": "O preço pelo qual o titular pode exercer o direito é o preço de exercício (strike).", "b": "O fluxo é inverso: quem paga o prêmio é o titular, e quem recebe é o lançador.", "d": "O titular paga o prêmio, mas a margem de garantia é exigida de quem assume a obrigação, o lançador."}, "96": {"b": "S < K torna positivo o valor intrínseco da opção de venda (put), e não da call.", "c": "Com S = K o valor intrínseco da call é zero.", "d": "O valor intrínseco da call é zero sempre que S ≤ K."}, "97": {"a": "Negociação em bolsa com vencimentos padronizados é característica das opções listadas, e não das flexíveis.", "c": "Nas opções flexíveis as características são definidas pelas partes; não há imposição de estilo ou forma de liquidação.", "d": "Não há restrição de público a investidores não residentes."}, "98": {"a": "1.000 pontos não é o valor do DI1 no vencimento; o PU é de 100.000 pontos.", "b": "10.000 pontos não corresponde ao PU de vencimento do DI1.", "d": "O PU no vencimento é de 100.000 pontos, e não de 1 milhão."}, "99": {"a": "Os vencimentos não são mensais; ocorrem a cada dois meses.", "c": "Os vencimentos não são trimestrais; são bimestrais.", "d": "Os vencimentos são bimestrais, mas nos meses pares, e não nos ímpares."}, "100": {"b": "No swap não há troca de propriedade de ativos, mas de fluxos financeiros calculados sobre um valor de referência.", "c": "Direito sem obrigação é característica das opções, e não do swap.", "d": "Ajustes diários padronizados em bolsa são próprios dos contratos futuros."}, "101": {"a": "As debêntures simples pagam remuneração e principal, sem possibilidade de troca por ações.", "b": "As conversíveis permitem a troca por ações da própria companhia emissora, e não de outra empresa.", "d": "Incentivadas são debêntures com benefício tributário para financiar infraestrutura; a classificação não trata de troca por ações."}, "102": {"b": "Título bancário com lastro em créditos do agronegócio é a LCA, e não a CPR.", "c": "Certificado de securitizadora com lastro imobiliário é o CRI.", "d": "A CPR é um título privado do agronegócio, e não um título público."}, "103": {"a": "Junho e dezembro não são os meses do come-cotas; o recolhimento ocorre em maio e novembro.", "b": "Março e setembro não são os meses previstos.", "d": "Janeiro e julho não são os meses previstos; o correto é maio e novembro."}, "104": {"b": "R$ 35 mil é o limite de isenção para a venda de outros bens, e não de ações no mercado à vista.", "c": "R$ 10 mil não é o limite previsto; o valor é R$ 20 mil em alienações no mês.", "d": "R$ 50 mil não é o limite previsto para a isenção em ações."}, "105": {"a": "0,005% na fonte e 15% ao mês são as alíquotas das operações comuns, e não do day trade.", "c": "A retenção de 1% está correta, mas a alíquota mensal do day trade é de 20%, e não 15%.", "d": "A alíquota mensal de 20% está correta, mas a retenção na fonte do day trade é de 1%, e não 0,005%."}, "106": {"a": "O conselho tem 12 membros, e a exigência é de pelo menos dois terços independentes, não apenas maioria.", "b": "O número de membros e a proporção de independentes estão incorretos: são 12 membros, com pelo menos dois terços independentes.", "c": "O número de membros está certo, mas a exigência é de pelo menos dois terços independentes, e não de todos."}};Object.keys(WHY3).forEach(function(k){WHY[k]=WHY[k]||{};Object.keys(WHY3[k]).forEach(function(l){WHY[k][l]=WHY3[k][l]})});
var WHY4={"107":{"b":"O Presidente da República e o Presidente da CVM não integram o CMN.","c":"CVM e Susep são órgãos supervisores que seguem as diretrizes do CMN, mas não o compõem.","d":"A B3 é uma infraestrutura de mercado privada e não integra o CMN."},"108":{"a":"US$ 10.000,00 é o tamanho do minicontrato de dólar (WDO), e não do contrato padrão.","b":"US$ 25.000,00 não corresponde a nenhum dos contratos de dólar descritos no guia.","d":"O contrato padrão tem US$ 50.000,00, e não US$ 100.000,00."},"109":{"a":"US$ 1.000,00 não é o tamanho do minicontrato de dólar.","b":"US$ 5.000,00 não é o tamanho do minicontrato de dólar.","c":"US$ 50.000,00 é o tamanho do contrato padrão (DOL), e não do minicontrato."},"110":{"b":"O último dia útil do mês anterior não é a data de vencimento; os contratos vencem no primeiro dia útil do mês de vencimento.","c":"A quarta-feira mais próxima do dia 15 é a regra de vencimento do futuro de Ibovespa, e não do dólar.","d":"Dia 15 não é a regra de vencimento dos contratos de dólar."},"111":{"a":"Os recursos próprios da B3 ficam entre as últimas camadas da cadeia de salvaguardas, e não na primeira.","c":"As contribuições dos membros adimplentes (survivors pay) só são usadas depois de esgotadas as camadas anteriores.","d":"O fundo de liquidação é acionado depois das garantias do comitente e dos intermediários."},"112":{"a":"A CORE é uma metodologia de risco, e não de cálculo de tributos.","b":"Os horários de negociação são definidos pela B3 em seus regulamentos e não têm relação com a CORE.","d":"A classificação em segmentos de listagem depende de regras de governança, e não da metodologia de risco."},"113":{"a":"5 minutos não é a duração mínima prevista para esse leilão.","c":"30 minutos não é a duração mínima prevista para o leilão especial.","d":"1 hora não é a duração mínima do leilão especial; é o tempo de interrupção do circuit breaker na queda de 15%."},"114":{"a":"“Alta” e “baixa” não são as categorias de túneis previstas.","b":"“Abertura” e “fechamento” são fases do pregão, e não tipos de túnel.","c":"“Liquidez” e “volatilidade” não são as categorias de túneis previstas."},"115":{"b":"O período antes da abertura é o pré-abertura (leilão de abertura), e não o after-market.","c":"O after-market acontece no próprio ambiente de bolsa, e não no balcão não organizado.","d":"O after-market é um período de negociação, e não uma janela de liquidação."},"116":{"a":"50% não é o percentual previsto na Lei das S.A.","b":"70% não é o percentual previsto na Lei das S.A.","d":"100% é o tag along exigido em segmentos especiais, como o Novo Mercado, e não o mínimo legal."},"117":{"a":"50% não é o percentual mínimo de distribuição previsto para os FII.","b":"75% não é o percentual mínimo de distribuição previsto para os FII.","c":"90% não é o percentual previsto; o mínimo é de 95% do lucro."},"118":{"a":"50 cotistas não é o número mínimo exigido para a isenção.","c":"500 cotistas não é o número exigido; o mínimo é de 100 cotistas.","d":"1.000 cotistas não é o número exigido; o mínimo é de 100 cotistas."},"119":{"b":"5% não é o limite previsto; o cotista pode ter até 10% das cotas.","c":"20% supera o limite individual de 10%.","d":"30% é o limite para o conjunto dos membros de uma família, e não para o cotista individual."},"120":{"a":"25% não é o percentual mínimo previsto para o FIDC.","b":"Um terço não é o percentual mínimo previsto para o FIDC.","d":"Dois terços não é o percentual previsto; o mínimo é de 50%."},"121":{"a":"O FIDC aplica principalmente em direitos creditórios, e não em participações societárias.","c":"O FII investe em empreendimentos e ativos imobiliários.","d":"O ETF replica um índice de mercado e tem cotas negociadas em bolsa."},"122":{"a":"90 dias é um prazo típico de títulos de curto prazo, e não o mínimo da LF.","b":"1 ano é inferior ao prazo mínimo de dois anos da LF.","c":"5 anos não é o prazo mínimo; a LF pode ter prazo a partir de dois anos."},"123":{"b":"R$ 300.000,00 é o valor mínimo da LF COM cláusula de subordinação.","c":"R$ 1.000,00 é muito inferior ao valor mínimo previsto para a LF.","d":"R$ 150.000,00 não é um dos valores mínimos previstos para a LF."},"124":{"a":"O título com promessa de entrega de produtos rurais é a CPR.","b":"O título de securitizadora com lastro imobiliário é o CRI.","d":"A LCA é um título privado, e não um título público federal."},"125":{"a":"Títulos bancários de longo prazo para crédito imobiliário são instrumentos como a LCI ou a LIG, e não as notas comerciais.","c":"As notas comerciais são títulos privados, e não públicos.","d":"Notas comerciais são títulos de dívida; a conversão em ações é característica das debêntures conversíveis."},"126":{"a":"15% é a menor alíquota da tabela regressiva, mas não se aplica às debêntures incentivadas para pessoa física.","b":"22,5% é a alíquota da tabela regressiva para prazos de até 180 dias.","d":"As debêntures incentivadas têm regime próprio, com alíquota zero para pessoa física, e não seguem a tabela regressiva."},"127":{"a":"22,5% é a alíquota para prazos de até 180 dias.","c":"17,5% é a alíquota para prazos de 361 a 720 dias.","d":"15% é a alíquota para prazos acima de 720 dias."},"128":{"a":"20% vale para prazos de 181 a 360 dias.","c":"15% só vale para prazos acima de 720 dias.","d":"22,5% vale para prazos de até 180 dias."},"129":{"a":"0,38% é a alíquota do IOF em outras operações, como câmbio e crédito, e não a regra regressiva sobre o rendimento.","b":"Não há alíquota fixa mensal de IOF nesses resgates; ela é regressiva conforme os dias.","d":"22,5% a 15% é a faixa da tabela regressiva do Imposto de Renda, e não do IOF."},"130":{"a":"O CMN é o órgão normativo do SFN e fixa a meta de inflação, mas não define a meta da Selic.","c":"O CRSFN julga recursos contra sanções administrativas, sem papel na política de juros.","d":"A CVM regula o mercado de valores mobiliários e não define a política monetária."},"131":{"a":"A LTN é o Tesouro Prefixado (sem cupom), e não o título indexado ao IPCA.","b":"A LFT é o Tesouro Selic, título pós-fixado.","c":"A NTN-F é o Tesouro Prefixado com juros semestrais."},"132":{"a":"Não há prazo de 48 horas contado da operação; o prazo é de 24 horas a partir da conclusão da análise.","c":"5 dias úteis não é o prazo da norma; a comunicação deve ocorrer em até 24 horas após a análise.","d":"30 dias após o mês da operação não é o prazo de comunicação de operações suspeitas ao Coaf."},"133":{"a":"1 ano é inferior ao mínimo exigido; a guarda deve ser de pelo menos 5 anos.","b":"2 anos não atende à exigência da norma, que é de no mínimo 5 anos.","d":"10 anos não é o prazo mínimo previsto; a norma exige pelo menos 5 anos."},"134":{"b":"A Lei nº 12.965/2014 é o Marco Civil da Internet; não criou a ANPD e a LGPD trata de pessoas naturais.","c":"A Lei nº 9.613/1998 é a Lei de Lavagem de Dinheiro, não a LGPD.","d":"A LC nº 105/2001 trata do sigilo bancário; as bases legais de tratamento estão na LGPD."},"135":{"a":"6 meses não é a periodicidade prevista; o limite é de 24 meses.","b":"12 meses não é o intervalo definido na norma; o máximo é de 24 meses.","c":"36 meses excede o limite; a reavaliação deve ocorrer em até 24 meses."},"136":{"a":"A primeira linha é a gestão operacional, que executa os processos e controla os riscos no dia a dia.","b":"A segunda linha reúne controles internos, gestão de riscos e compliance, não a auditoria interna.","d":"A quarta linha corresponde à auditoria externa e aos reguladores."},"137":{"b":"A Resolução CVM nº 30/2021 trata de suitability, não de estrutura de gerenciamento de riscos.","c":"A Resolução CMN nº 4.945/2021 trata da PRSAC (responsabilidade social, ambiental e climática).","d":"A Resolução CVM nº 50/2021 trata de PLD/FTP."},"138":{"a":"O RDE é o Registro Declaratório Eletrônico do Bacen, usado nos capitais de investidores não residentes.","c":"O Sisbacen é o sistema de informações do Banco Central, não o cadastro da B3.","d":"CORE é a metodologia de cálculo de risco da Câmara B3, não um sistema de cadastro."},"139":{"a":"A conta máster não é conta de depósito definitiva; as operações são alocadas depois aos beneficiários finais.","b":"A conta máster não é exclusiva de não residentes nem é aberta pelo representante legal.","d":"A conta máster não é conta de garantia; serve para agrupar ordens para posterior alocação."},"140":{"a":"Os ativos não passam a integrar o patrimônio da B3 em nenhum momento; ficam segregados.","b":"A B3 não pode usar ativos de comitentes para cobrir perdas de outros participantes, pois eles são segregados.","c":"O agente de custódia não é proprietário dos ativos; a titularidade é do comitente."},"141":{"b":"O controle sintético registra apenas a quantidade consolidada, sem datas e custos de aquisição.","c":"Fungível não é uma modalidade de controle de saldos; descreve ativos intercambiáveis entre si.","d":"Consolidado não é o nome da modalidade que registra custos e datas de aquisição."}};Object.keys(WHY4).forEach(function(k){WHY[k]=WHY[k]||{};Object.keys(WHY4[k]).forEach(function(l){WHY[k][l]=WHY4[k][l]})});
